BOOK_DATA = [{'page_no': 1, 'title': 'The Studio of Basil Hallward', 'tr_title': "Basil Hallward'ın Atölyesi", 'vocab_focus': [('studio', 'sanat atölyesi'), ('lilac', 'leylak'), ('canvas', 'tuval'), ('masterpiece', 'şaheser, başyapıt'), ('cynical', 'alaycı, insanlara güvenmeyen'), ('exhibit', 'sergilemek'), ('flattery', 'dalkavukluk, aşırı övgü'), ('intellect', 'zeka, akıl')], 'sentences': [{'id': 1, 'text': 'The studio was filled with the rich, sweet odor of summer roses and delicate purple lilacs.', 'translation': 'Sanat atölyesi yaz güllerinin ve narin mor leylakların zengin, tatlı kokusuyla doluydu.', 'notes': 'sweet odor: tatlı koku.'}, {'id': 2, 'text': 'Lord Henry Wotton lay reclining upon a divan of Persian saddlebags, smoking his countless opium-scented cigarettes.', 'translation': 'Lord Henry Wotton, afyon kokulu sayısız sigarasını tüttürerek İran heybesinden yapılmış bir divana uzanmıştı.', 'notes': 'lay reclining: uzanmış yatıyordu.'}, {'id': 3, 'text': 'In the center of the sunlit room stood the full-length portrait of a young man of extraordinary personal beauty.', 'translation': 'Güneş alan odanın tam ortasında, olağanüstü kişisel güzellikte genç bir adamın boydan boya portresi duruyordu.', 'notes': 'full-length portrait: boy portresi.'}, {'id': 4, 'text': 'Sitting before it was the painter himself, Basil Hallward, gazing at his creation with quiet reverence.', 'translation': 'Önünde oturan kişi ise yarattığı esere sessiz bir hürmetle bakan ressamın bizzat kendisi, Basil Hallward idi.', 'notes': 'quiet reverence: sessiz hürmet.'}, {'id': 5, 'text': '"It is your finest work, Basil, the best thing you have ever done," Lord Henry said languidly.', 'translation': '"Bu senin en harika eserin Basil, şimdiye kadar yaptığın en güzel şey," dedi Lord Henry uyuşuk bir tavırla.', 'notes': 'said languidly: uyuşukça/aheste söyledi.'}, {'id': 6, 'text': '"You must certainly send it next year to the Grosvenor Gallery to be admired by all London."', 'translation': '"Bütün Londra\'nın hayran kalması için onu gelecek yıl kesinlikle Grosvenor Galerisi\'ne göndermelisin."', 'notes': 'admired by all: herkesçe hayran kalınan.'}, {'id': 7, 'text': '"No," the painter answered, tossing his head back with a resolute frown; "I shall not exhibit it anywhere."', 'translation': '"Hayır," diye yanıtladı ressam, kararlı bir kaş çatışıyla başını geriye atarak; "Onu hiçbir yerde sergilemeyeceğim."', 'notes': 'resolute frown: kararlı kaş çatış.'}, {'id': 8, 'text': 'Lord Henry elevated his dark eyebrows and looked at him in genuine bewilderment.', 'translation': 'Lord Henry koyu kaşlarını yukarı kaldırdı ve samimi bir şaşkınlıkla ona baktı.', 'notes': 'genuine bewilderment: samimi şaşkınlık.'}, {'id': 9, 'text': '"Not exhibit it? What an extraordinary whim! An artist should do anything in the world to gain reputation!"', 'translation': '"Sergilememek mi? Ne tuhaf bir heves! Bir sanatçı şöhret kazanmak için dünyadaki her şeyi yapmalıdır!"', 'notes': 'gain reputation: itibar/şöhret kazanmak.'}, {'id': 10, 'text': '"There is only one thing in the world worse than being talked about, and that is not being talked about."', 'translation': '"Dünyada hakkında konuşulmasından daha kötü olan tek bir şey vardır; o da hakkında hiç konuşulmamasıdır."', 'notes': 'not being talked about: hakkında konuşulmaması.'}, {'id': 11, 'text': '"I know you will laugh at me, Henry," Basil replied softly, "but I really cannot exhibit it."', 'translation': '"Bana güleceğini biliyorum Henry," diye usulca yanıtladı Basil, "fakat onu gerçekten sergileyemem."', 'notes': 'replied softly: usulca yanıtladı.'}, {'id': 12, 'text': '"I have put too much of myself into this canvas; it reveals the secret of my own soul."', 'translation': '"Ben bu tuvale kendimden çok fazla şey kattım; bu resim kendi ruhumun sırrını açığa vuruyor."', 'notes': 'secret of my own soul: kendi ruhumun sırrı.'}, {'id': 13, 'text': 'Lord Henry laughed his cynical, musical laugh: "Too much of yourself! Upon my word, Basil, you look nothing like him!"', 'translation': 'Lord Henry o alaycı, melodik kahkahasını attı: "Kendinden çok fazla şey mi! Sözüme inan Basil, ona hiç benzemiyorsun!"', 'notes': 'cynical musical laugh: alaycı melodik kahkaha.'}, {'id': 14, 'text': '"This young Adonis has a face of ivory and rose leaves, while you possess a rugged, intellectual countenance."', 'translation': '"Bu genç Adonis fil dişi ve gül yapraklarından bir yüze sahipken, senin sert ve entelektüel bir çehren var."', 'notes': 'ivory and rose leaves: fil dişi ve gül yaprakları.'}, {'id': 15, 'text': '"You do not understand me, Harry," Basil said gravely; "it is not his physical resemblance to me that I fear."', 'translation': '"Beni anlamıyorsun Harry," dedi Basil ciddiyetle; "korktuğum şey bana olan fiziksel benzerliği değil."', 'notes': 'physical resemblance: fiziksel benzerlik.'}, {'id': 16, 'text': '"His personality has exerted an extraordinary fascination over me from the moment we first met."', 'translation': '"Onun kişiliği, ilk tanıştığımız andan itibaren üzerimde olağanüstü bir büyüleyici etki yarattı."', 'notes': 'extraordinary fascination: olağanüstü büyülenme/etki.'}, {'id': 17, 'text': '"He dominates my entire art, my style, and my creative imagination."', 'translation': '"Bütün sanatıma, üslubuma ve yaratıcı hayal gücüme o hükmediyor."', 'notes': 'dominates my art: sanatıma hükmediyor.'}, {'id': 18, 'text': '"What is the name of this wonderful young gentleman?" Lord Henry asked with intense curiosity.', 'translation': '"Bu harika genç beyefendinin adı nedir?" diye sordu Lord Henry yoğun bir merakla.', 'notes': 'intense curiosity: yoğun merak.'}, {'id': 19, 'text': 'Basil hesitated, reluctant to speak the sacred name aloud: "His name is Dorian Gray."', 'translation': 'Kutsal adı yüksek sesle telaffuz etmekte tereddüt eden Basil gönülsüzce: "Adı Dorian Gray," dedi.', 'notes': 'reluctant to speak: söylemekte gönülsüz.'}, {'id': 20, 'text': 'Just at that moment, the butler stepped into the studio, announcing that Mr. Dorian Gray was waiting in the garden.', 'translation': "Tam o anda uşak atölyeye adım attı ve Bay Dorian Gray'in bahçede beklediğini duyurdu.", 'notes': 'announced: duyurdu, bildirdi.'}]}, {'page_no': 2, 'title': 'Lord Henry Meets Dorian Gray', 'tr_title': 'Lord Henry Dorian Gray ile Tanışıyor', 'vocab_focus': [('radiant', 'ışıl ışıl, parlak'), ('unspoiled', 'bozulmamış, saf'), ('influence', 'etkilemek, nüfuz'), ('philosophy', 'felsefe'), ('ephemeral', 'geçici, fani'), ('wrinkle', 'kırışıklık'), ('revelation', 'vahiy, aydınlanma'), ('spellbound', 'büyülenmiş, kendinden geçmiş')], 'sentences': [{'id': 21, 'text': 'Before Dorian entered, Basil turned to Lord Henry with an earnest and passionate entreaty.', 'translation': "Dorian içeri girmeden önce Basil samimi ve tutkulu bir yalvarışla Lord Henry'ye döndü.", 'notes': 'passionate entreaty: tutkulu yalvarış.'}, {'id': 22, 'text': '"Dorian Gray is my dearest friend; his nature is completely pure and unspoiled," Basil pleaded.', 'translation': '"Dorian Gray benim en sevgili dostumdur; doğası tamamen saf ve bozulmamıştır," diye yalvardı Basil.', 'notes': 'pure and unspoiled: saf ve bozulmamış.'}, {'id': 23, 'text': '"Do not try to influence him with your cynical paradoxes; do not spoil the only thing that makes my art divine!"', 'translation': '"Alaycı paradokslarınla onu etkilemeye çalışma; sanatımı ilahi kılan tek şeyi berbat etme!"', 'notes': 'cynical paradoxes: alaycı paradokslar/çelişkiler.'}, {'id': 24, 'text': 'Lord Henry only smiled his languid smile as the studio door opened and Dorian Gray stepped inside.', 'translation': 'Atölye kapısı açılıp Dorian Gray içeri adım atarken Lord Henry yalnızca o uyuşuk tebessümüyle gülümsedi.', 'notes': 'languid smile: uyuşuk/aheste tebessüm.'}, {'id': 25, 'text': 'Dorian was undeniably handsome, with finely curved scarlet lips, frank blue eyes, and crisp golden hair.', 'translation': 'Dorian ince kıvrımlı al dudakları, dürüst mavi gözleri ve dalgalı altın sarısı saçlarıyla inkâr edilemez derecede yakışıklıydı.', 'notes': 'scarlet lips: al/kırmızı dudaklar.'}, {'id': 26, 'text': 'There was something in his open, youthful face that made one trust him at once.', 'translation': 'Açık ve genç yüzünde insanı ona derhal güvenmeye sevk eden bir şey vardı.', 'notes': 'trust him at once: ona derhal güvenmek.'}, {'id': 27, 'text': "All the candor of youth was there, along with youth's passionate purity.", 'translation': 'Gençliğin tüm samimiyeti ve gençliğin o tutkulu saflığı oradaydı.', 'notes': 'candor of youth: gençliğin samimiyeti/açık sözlülüğü.'}, {'id': 28, 'text': 'While Basil prepared his brushes and palette, Dorian complained of being fatigued by standing on the platform.', 'translation': 'Basil fırçalarını ve paletini hazırlarken Dorian platformda ayakta durmaktan yorulduğundan yakındı.', 'notes': 'palette: ressam paleti.'}, {'id': 29, 'text': '"Come into the garden, Dorian, and sit in the shade while I mix the colors," Lord Henry suggested smoothly.', 'translation': '"Bahçeye gel Dorian ve ben renkleri karıştırırken gölgede otur," diye tatlı tatlı önerdi Lord Henry.', 'notes': 'suggested smoothly: tatlı tatlı/yumuşakça önerdi.'}, {'id': 30, 'text': 'In the cool shade of a flowering laurel tree, Lord Henry began to weave his seductive philosophy.', 'translation': 'Çiçek açmış bir defne ağacının serin gölgesinde Lord Henry o baştan çıkarıcı felsefesini örmeye başladı.', 'notes': 'seductive philosophy: baştan çıkarıcı felsefe.'}, {'id': 31, 'text': '"There is nothing in the world of any real value except youth!" Lord Henry murmured in his musical voice.', 'translation': '"Dünyada gençlik dışında gerçek değeri olan hiçbir şey yoktur!" diye mırıldandı Lord Henry o melodik sesiyle.', 'notes': 'musical voice: melodik/müzikal ses.'}, {'id': 32, 'text': '"Youth is the one thing worth having, for beauty is a form of genius—higher indeed than genius."', 'translation': '"Gençlik sahip olmaya değer yegane şeydir zira güzellik bir deha biçimidir—gerçekten dehadan bile üstündür."', 'notes': 'form of genius: bir deha biçimi.'}, {'id': 33, 'text': '"People say that beauty is shallow, but it is not nearly so shallow as thought."', 'translation': '"İnsanlar güzelliğin yüzeysel olduğunu söylerler fakat güzellik kesinlikle düşünce kadar yüzeysel değildir."', 'notes': 'shallow: yüzeysel, sığ.'}, {'id': 34, 'text': '"To me, beauty is the wonder of wonders; only shallow people do not judge by appearances."', 'translation': '"Bana göre güzellik harikalar harikasıdır; yalnızca sığ insanlar görünüşe göre hüküm vermezler."', 'notes': 'wonder of wonders: harikalar harikası.'}, {'id': 35, 'text': '"Ah, realize your youth while you have it! Don\'t squander your gold on tedious, common things!"', 'translation': '"Ah, elindeyken gençliğinin kıymetini bil! Altınını sıkıcı ve sıradan şeylere harcayıp heba etme!"', 'notes': "don't squander: heba etme, saçıp savurma."}, {'id': 36, 'text': '"Time is jealous of you, Dorian; the days will come when wrinkles will ruin your smooth brow."', 'translation': '"Zaman seni kıskanıyor Dorian; kırışıklıkların o pürüzsüz alnını mahvedeceği günler gelecektir."', 'notes': 'time is jealous: zaman kıskançtır.'}, {'id': 37, 'text': '"Your cheeks will grow hollow and pale, your eyes will become dull, and you will suffer horribly!"', 'translation': '"Yanakların çökecek ve solacak, gözlerin ferini kaybedecek ve korkunç bir acı çekeceksin!"', 'notes': 'grow hollow: çökmek.'}, {'id': 38, 'text': '"Now, wherever you go, you charm the entire world; will it always be so?"', 'translation': '"Şimdi nereye gitsen bütün dünyayı büyülüyorsun; bu hep böyle mi kalacak sanıyorsun?"', 'notes': 'charm the entire world: tüm dünyayı büyülemek.'}, {'id': 39, 'text': 'Dorian listened spellbound, feeling strange, new pulses of thought awakening within his soul.', 'translation': 'Dorian büyülenmiş halde dinledi; ruhunun içinde düşüncenin garip, yeni nabız atışlarının uyandığını hissetti.', 'notes': 'new pulses of thought: yeni düşünce nabızları.'}, {'id': 40, 'text': 'Words had never seemed so musical, so seductive, and so terrifyingly true.', 'translation': 'Kelimeler hiç bu kadar ahenkli, bu kadar baştan çıkarıcı ve bu kadar korkunç derecede doğru gelmemişti.', 'notes': 'terrifyingly true: korkutucu derecede doğru.'}]}, {'page_no': 3, 'title': 'The Fatal Wish Before the Canvas', 'tr_title': 'Tuvalin Karşısındaki Ölümcül Dilek', 'vocab_focus': [('masterpiece', 'başyapıt, şaheser'), ('transfix', 'donakalmak, büyülenmek'), ('jealousy', 'kıskançlık'), ('decay', 'çürüme, yaşlanma'), ('sacrifice', 'fedakarlık, kurban etme'), ('outburst', 'öfke patlaması, haykırış'), ('palette-knife', 'spatula, ressam bıçağı'), ('gift', 'hediye, armağan')], 'sentences': [{'id': 41, 'text': 'Basil called them back into the studio to apply the final, delicate touches of paint to the portrait.', 'translation': 'Basil portreye son, narin boya dokunuşlarını uygulamak için onları atölyeye geri çağırdı.', 'notes': 'delicate touches: narin dokunuşlar.'}, {'id': 42, 'text': 'After a quarter of an hour of intense concentration, the painter stepped back from the easel.', 'translation': 'On beş dakikalık yoğun bir konsantrasyonun ardından ressam şövaleden geriye bir adım attı.', 'notes': 'easel: ressam şövalesi.'}, {'id': 43, 'text': '"It is finished!" Basil announced with quiet triumph, signing his name in long vermilion letters in the corner.', 'translation': '"Bitti!" diye ilan etti Basil sessiz bir zaferle; köşeye uzun parlak kırmızı harflerle adını imzalayarak.', 'notes': 'quiet triumph: sessiz zafer.'}, {'id': 44, 'text': 'Lord Henry came forward and examined the canvas: "My dear fellow, I congratulate you warmly; it is the masterpiece of our age!"', 'translation': 'Lord Henry öne çıktı ve tuvali inceledi: "Sevgili dostum, seni içtenlikle tebrik ederim; çağımızın başyapıtı bu!"', 'notes': 'masterpiece of our age: çağımızın başyapıtı.'}, {'id': 45, 'text': 'Dorian walked slowly to the easel and stood transfixed before his own painted image.', 'translation': 'Dorian yavaşça şövaleye yürüdü ve kendi resmedilmiş görüntüsünün karşısında donakaldı.', 'notes': 'stood transfixed: donakaldı, büyülendi.'}, {'id': 46, 'text': 'His cheeks flushed with pleasure as he beheld the radiant splendor of his own youth for the first time.', 'translation': 'Kendi gençliğinin ışıl ışıl görkemini ilk kez seyrederken yanakları hazla al al oldu.', 'notes': 'radiant splendor: ışıltılı görkem.'}, {'id': 47, 'text': 'He saw the wonder of his own beauty as if looking upon a magnificent stranger.', 'translation': 'Kendi güzelliğinin harikasını sanki muhteşem bir yabancıya bakıyormuş gibi gördü.', 'notes': 'magnificent stranger: muhteşem yabancı.'}, {'id': 48, 'text': "Then, like a sharp dagger of ice, Lord Henry's warning pierced his beating heart.", 'translation': "Derken keskin bir buz hançeri gibi Lord Henry'nin uyarısı çarpan kalbini delip geçti.", 'notes': 'dagger of ice: buz hançeri.'}, {'id': 49, 'text': 'The day would come when this marvelous face would wither, yellow, and wrinkle into hideous decay!', 'translation': 'Bu harika yüzün solup sararacağı ve korkunç bir çürümeyle kırışacağı gün mutlaka gelecekti!', 'notes': 'hideous decay: korkunç çürüme/yıpranma.'}, {'id': 50, 'text': 'This canvas would mock him with its eternal youth while he became an unsightly, doddering old wreck.', 'translation': 'Kendisi çirkin, titrek yaşlı bir enkaza dönerken bu tuval ebedi gençliğiyle onunla alay edecekti.', 'notes': 'doddering old wreck: titrek yaşlı enkaz.'}, {'id': 51, 'text': 'A sharp tear welled in his blue eyes, and his hands clenched into trembling fists.', 'translation': 'Mavi gözlerinde yakıcı bir gözyaşı belirdi ve elleri titreyen yumruklar halinde sıkıldı.', 'notes': 'hands clenched: eller sıkıldı.'}, {'id': 52, 'text': '"How sad it is!" Dorian murmured, tears running down his flushed cheeks.', 'translation': '"Ne kadar da hüzünlü!" diye mırıldandı Dorian, kızarmış yanaklarından gözyaşları süzülerek.', 'notes': 'tears running down: gözyaşları süzülerek.'}, {'id': 53, 'text': '"I shall grow old, and horrible, and dreadful. But this picture will remain always young."', 'translation': '"Ben yaşlanacağım, korkunç ve berbat bir hale geleceğim. Fakat bu resim her zaman genç kalacak."', 'notes': 'remain always young: her zaman genç kalmak.'}, {'id': 54, 'text': '"It will never be older than this particular day of June. If it were only the other way!"', 'translation': '"Bu haziran gününden asla daha yaşlı olmayacak. Keşke tam tersi olsaydı!"', 'notes': 'the other way: tam tersi.'}, {'id': 55, 'text': '"If it were I who was to be always young, and the picture that was to grow old!"', 'translation': '"Keşke her zaman genç kalacak olan ben olsaydım ve yaşlanacak olan şu resim olsaydı!"', 'notes': 'grow old: yaşlanmak.'}, {'id': 56, 'text': '"For that—for that—I would give everything in the world! Yes, there is nothing in the whole world I would not give!"', 'translation': '"Bunun için—bunun için—dünyadaki her şeyimi verirdim! Evet, bütün dünyada vermeyeceğim hiçbir şey yok!"', 'notes': 'give everything: her şeyi vermek.'}, {'id': 57, 'text': '"I would give my very soul for that!" Dorian cried out in an agony of wild passion.', 'translation': '"Bunun uğruna bizzat ruhumu bile verirdim!" diye haykırdı Dorian vahşi bir tutkunun ızdırabı içinde.', 'notes': 'give my very soul: bizzat ruhumu vermek.'}, {'id': 58, 'text': 'Basil was startled by the boy\'s frantic outburst: "I cannot bear to see you unhappy, Dorian!"', 'translation': 'Çocuğun bu çılgınca haykırışıyla irkilen Basil: "Seni mutsuz görmeye dayanamam Dorian!" dedi.', 'notes': 'frantic outburst: çılgınca haykırış.'}, {'id': 59, 'text': 'The painter seized a palette-knife to slash the canvas, but Dorian threw himself between Basil and the picture.', 'translation': 'Ressam tuvali yırtmak için bir spatula kaptı fakat Dorian kendisini Basil ile resmin arasına attı.', 'notes': 'slash the canvas: tuvali parçalamak/yırtmak.'}, {'id': 60, 'text': '"Don\'t, Basil, don\'t! It would be murder! It is part of myself; give it to me!" Dorian begged.', 'translation': '"Yapma Basil, sakın! Bu bir cinayet olur! O benim bir parçam; onu bana ver!" diye yalvardı Dorian.', 'notes': 'it would be murder: bu cinayet olurdu.'}]}, {'page_no': 4, 'title': 'The Actress in the Slums', 'tr_title': 'Varoşlardaki Kadın Oyuncu', 'vocab_focus': [('slum', 'varoş, kenar mahalle'), ('theatre', 'tiyatro'), ('tragedy', 'trajedi, acıklı oyun'), ('actress', 'kadın oyuncu'), ('genius', 'deha'), ('romance', 'aşk, romantizm'), ('fascinate', 'büyülemek'), ('enthralled', 'kendinden geçmiş, mest olmuş')], 'sentences': [{'id': 61, 'text': "A few weeks later, Dorian burst into Lord Henry's library in Mayfair, his eyes sparkling with ecstatic joy.", 'translation': "Birkaç hafta sonra Dorian gözleri kendinden geçmiş bir sevinçle parıldayarak Lord Henry'nin Mayfair'deki kütüphanesine daldı.", 'notes': 'ecstatic joy: kendinden geçmiş bir sevinç.'}, {'id': 62, 'text': '"Harry, congratulate me! I am passionately in love!" Dorian proclaimed, pacing across the room.', 'translation': '"Harry tebrik et beni! Çılgınlar gibi aşığım!" diye ilan etti Dorian odada volta atarak.', 'notes': 'passionately in love: çılgınca aşık.'}, {'id': 63, 'text': '"Indeed? And who is the fortunate lady who has captured your heart?" Lord Henry inquired with amused indifference.', 'translation': '"Öyle mi? Peki kalbini esir alan o şanslı hanımefendi kimdir?" diye sordu Lord Henry eğlenmiş bir kayıtsızlıkla.', 'notes': 'amused indifference: eğlenen kayıtsızlık.'}, {'id': 64, 'text': '"Her name is Sibyl Vane, and she is an actress," Dorian answered with reverent enthusiasm.', 'translation': '"Adı Sibyl Vane ve o bir tiyatro oyuncusu," diye yanıtladı Dorian hürmet dolu bir coşkuyla.', 'notes': 'reverent enthusiasm: hürmet dolu coşku.'}, {'id': 65, 'text': '"An actress? But ordinary actresses are terribly common and uninteresting," Lord Henry murmured.', 'translation': '"Bir oyuncu mu? Fakat sıradan oyuncular son derece bayağı ve sıkıcıdır," diye mırıldandı Lord Henry.', 'notes': 'terribly common: son derece bayağı/sıradan.'}, {'id': 66, 'text': '"Sibyl is not ordinary! She is divine, a true artistic genius of the highest magnitude!" Dorian defended fiercely.', 'translation': '"Sibyl sıradan biri değil! O ilahi bir varlık, en üst mertebeden gerçek bir sanat dehası!" diye şiddetle savundu Dorian.', 'notes': 'highest magnitude: en üst mertebe/büyüklük.'}, {'id': 67, 'text': 'Dorian recounted how, wandering through the squalid alleys of the East End, he had discovered a shabby, third-rate theatre.', 'translation': "Dorian Doğu Yakası'nın sefil ara sokaklarında gezinirken döküntü, üçüncü sınıf bir tiyatroyu nasıl keşfettiğini anlattı.", 'notes': 'squalid alleys: sefil ara sokaklar.'}, {'id': 68, 'text': 'The air was thick with the reek of cheap tobacco and beer, and the audience was coarse and noisy.', 'translation': 'Hava ucuz tütün ve biranın ağır kokusuyla doluydu ve seyirciler kaba saba ve gürültücüydü.', 'notes': 'reek of cheap tobacco: ucuz tütün kokusu.'}, {'id': 69, 'text': "Yet when the curtain rose on Shakespeare's Romeo and Juliet, an extraordinary vision stepped upon the dusty boards.", 'translation': "Fakat perde Shakespeare'in Romeo ve Juliet'i için açıldığında, o tozlu tahtaların üzerine olağanüstü bir siluet adım attı.", 'notes': 'dusty boards: tozlu sahne tahtaları.'}, {'id': 70, 'text': 'Sibyl Vane was only seventeen, with delicate features, dark hair coiled in plaits, and violet eyes that seemed to mirror heaven.', 'translation': 'Sibyl Vane henüz on yedi yaşındaydı; narin yüz hatları, örgüler halinde sarılmış koyu saçları ve cenneti yansıtan menekşe gözleri vardı.', 'notes': 'violet eyes: menekşe rengi gözler.'}, {'id': 71, 'text': 'Her voice was a flute of liquid music that transformed the crude scenery into a realm of golden poetry.', 'translation': 'Sesi o ilkel dekoru altın bir şiir diyarına dönüştüren berrak müzikten bir flüt gibiydi.', 'notes': 'flute of liquid music: berrak müzikten bir flüt.'}, {'id': 72, 'text': '"She was Rosalind one night, Imogen the next, and Juliet the night after," Dorian spoke passionately.', 'translation': '"Bir gece Rosalind oldu, ertesi gece Imogen ve ondan sonraki gece Juliet," dedi Dorian tutkuyla.', 'notes': 'spoke passionately: tutkuyla konuştu.'}, {'id': 73, 'text': '"I have seen her in every tragic and romantic role, and she has created them all anew with her genius."', 'translation': '"Onu her trajik ve romantik rolde izledim ve o dehasıyla hepsini adeta baştan yarattı."', 'notes': 'created anew: baştan yarattı.'}, {'id': 74, 'text': '"Have you spoken to her?" Lord Henry asked, blowing a smoke ring toward the ornate ceiling.', 'translation': '"Onunla hiç konuştun mu?" diye sordu Lord Henry süslü tavana doğru bir duman halkası üfleyerek.', 'notes': 'ornate ceiling: süslü tavan.'}, {'id': 75, 'text': '"Yes; after the third performance, I went backstage to meet her," Dorian smiled radiantly.', 'translation': '"Evet; üçüncü temsilden sonra onunla tanışmak için kulise gittim," diye ışıl ışıl gülümsedi Dorian.', 'notes': 'backstage: kulis, sahne arkası.'}, {'id': 76, 'text': '"She knows nothing of my title, my family, or my wealth; she calls me \'Prince Charming\'!"', 'translation': '"Unvanımdan, ailemden veya servetimden hiç haberi yok; bana \'Beyaz Atlı Prens\' diyor!"', 'notes': 'Prince Charming: Beyaz Atlı Prens.'}, {'id': 77, 'text': '"She regards me as a creature from a magical realm who has come to rescue her from poverty."', 'translation': '"Beni kendisini yoksulluktan kurtarmaya gelmiş büyülü bir diyardan bir varlık olarak görüyor."', 'notes': 'magical realm: büyülü diyar.'}, {'id': 78, 'text': '"You must come with me tonight, Harry, and Basil too; you must see her act Juliet!"', 'translation': '"Bu gece benimle gelmelisin Harry ve Basil de gelmeli; onu Juliet\'i oynarken mutlaka görmelisiniz!"', 'notes': 'must see her act: oynarken görmelisin.'}, {'id': 79, 'text': '"When you see her divine art, you will understand why I have pledged my eternal soul to her!"', 'translation': '"Onun o ilahi sanatını gördüğünüzde ebedi ruhumu neden ona adadığımı anlayacaksınız!"', 'notes': 'divine art: ilahi sanat.'}, {'id': 80, 'text': 'Lord Henry agreed with a cynical smirk, eager to study the psychological effects of first love upon his young protégé.', 'translation': 'Genç çömezi üzerindeki ilk aşkın psikolojik etkilerini incelemeye can atan Lord Henry alaycı bir sırıtışla kabul etti.', 'notes': 'cynical smirk: alaycı sırıtış.'}]}, {'page_no': 5, 'title': "Sibyl Vane's Vow and the Cruel Rejection", 'tr_title': "Sibyl Vane'in Yemini ve Zalimce Reddediliş", 'vocab_focus': [('sailor', 'denizci'), ('vengeance', 'intikam'), ('abominable', 'berbat, rezil'), ('lifeless', 'cansız, ruhsuz'), ('illusion', 'yanılsama, hayal'), ('hiss', 'yuhalama, ıslıklama'), ('shallow', 'sığ, yüzeysel'), ('rejection', 'reddetme, ret')], 'sentences': [{'id': 81, 'text': "That same afternoon, Sibyl's sixteen-year-old brother, James Vane, was preparing to sail for Australia as a merchant seaman.", 'translation': "Aynı öğleden sonra Sibyl'ın on altı yaşındaki erkek kardeşi James Vane ticaret denizcisi olarak Avustralya'ya yelken açmaya hazırlanıyordu.", 'notes': 'merchant seaman: ticaret denizcisi/bahriyelisi.'}, {'id': 82, 'text': 'James was a rough, heavily built lad with brown hair, deeply suspicious of the fine gentleman visiting his sister.', 'translation': 'James kahverengi saçlı, iri yarı, kaba saba bir delikanlıydı ve kız kardeşini ziyaret eden o kibar beyefendiden son derece kuşkulanıyordu.', 'notes': 'heavily built lad: iri yarı delikanlı.'}, {'id': 83, 'text': '"Listen to me, mother," James growled sternly before departing; "if that Prince Charming ever harms Sibyl, I shall kill him like a dog!"', 'translation': '"Beni dinle anne," diye ayrılmadan önce sertçe hırladı James; "eğer o Beyaz Atlı Prens Sibyl\'a zarar verecek olursa onu bir köpek gibi gebertirim!"', 'notes': 'kill like a dog: köpek gibi öldürmek.'}, {'id': 84, 'text': 'That evening, Dorian, Lord Henry, and Basil Hallward arrived at the dingy East End theatre.', 'translation': "O akşam Dorian, Lord Henry ve Basil Hallward Doğu Yakası'ndaki o döküntü tiyatroya vardılar.", 'notes': 'dingy theatre: döküntü/kasvetli tiyatro.'}, {'id': 85, 'text': "The theatre was hot and crowded, reeking of cheap beer and oranges, but Dorian's eyes shone with romantic anticipation.", 'translation': "Tiyatro sıcak ve tıklım tıklımdı; ucuz bira ve portakal kokuyordu fakat Dorian'ın gözleri romantik bir beklentiyle parlıyordu.", 'notes': 'romantic anticipation: romantik beklenti.'}, {'id': 86, 'text': 'When Sibyl stepped onto the stage as Juliet, she looked exquisitely lovely in her pale silk Renaissance gown.', 'translation': 'Sibyl sahneye Juliet olarak adım attığında, soluk ipek Rönesans elbisesi içinde son derece güzel görünüyordu.', 'notes': 'silk Renaissance gown: ipek Rönesans elbisesi.'}, {'id': 87, 'text': 'Yet the moment she began to speak, an appalling disappointment struck the heart of every spectator.', 'translation': 'Fakat konuşmaya başladığı an korkunç bir hayal kırıklığı her seyircinin yüreğini vurdu.', 'notes': 'appalling disappointment: korkunç hayal kırıklığı.'}, {'id': 88, 'text': 'Her voice was flat, mechanical, and devoid of all genuine emotion; her gestures were wooden and ridiculous.', 'translation': 'Sesi tekdüze, mekanik ve tüm sahici duygulardan yoksundu; hareketleri kaskatı ve gülünçtü.', 'notes': 'wooden gestures: kaskatı/odunsu hareketler.'}, {'id': 89, 'text': 'The greatest love poetry ever written sounded like the lifeless recitation of a dull schoolgirl.', 'translation': 'Şimdiye kadar yazılmış en muazzam aşk şiirleri, donuk bir kız öğrencinin cansız ezber okuyuşu gibi tınlıyordu.', 'notes': 'lifeless recitation: cansız ezber okuma.'}, {'id': 90, 'text': 'The audience grew restless, whistling and laughing derisively at her pathetic performance.', 'translation': 'Seyirciler huzursuzlaştı; ıslık çalıp onun bu acınası performansıyla alaycı şekilde kahkahalar attılar.', 'notes': 'laughing derisively: alaycı şekilde gülerek.'}, {'id': 91, 'text': 'Dorian grew pale as death, slumping in his chair while cold perspiration beaded upon his forehead.', 'translation': 'Alnında soğuk ter damlaları birikirken koltuğuna yığılan Dorian ölüm gibi bembeyaz oldu.', 'notes': 'slumping in his chair: koltuğuna yığılarak.'}, {'id': 92, 'text': '"She is very beautiful, Dorian," Lord Henry said with polite pity, "but she cannot act; let us go."', 'translation': '"Çok güzel bir kız Dorian," dedi Lord Henry kibar bir acımayla, "fakat rol yapamıyor; hadi gidelim."', 'notes': 'polite pity: kibar acıma.'}, {'id': 93, 'text': 'Basil added gently: "Do not be sad, Dorian; she must be ill tonight; she will act divinely another time."', 'translation': 'Basil nazikçe ekledi: "Üzülme Dorian; bu gece hasta olmalı; başka bir zaman ilahi şekilde oynayacaktır."', 'notes': 'act divinely: ilahi şekilde oynamak.'}, {'id': 94, 'text': '"I wish she were dead!" Dorian hissed, his face twisted in humiliated vanity and fury.', 'translation': '"Keşke ölseydi!" diye tısladı Dorian; yüzü aşağılanmış bir kibir ve öfkeyle çarpılmıştı.', 'notes': 'humiliated vanity: aşağılanmış kibir.'}, {'id': 95, 'text': "After his friends departed, Dorian rushed backstage into Sibyl's dressing room in an uncontrolled rage.", 'translation': "Dostları ayrıldıktan sonra Dorian kontrolsüz bir öfke içinde sahne arkasına Sibyl'ın soyunma odasına daldı.", 'notes': 'dressing room: soyunma odası.'}, {'id': 96, 'text': 'Sibyl was standing alone, her face radiant with pure, ecstatic happiness.', 'translation': 'Sibyl tek başına duruyordu; yüzü saf, kendinden geçmiş bir mutlulukla ışıldıyordu.', 'notes': 'radiant with happiness: mutlulukla ışıldayan.'}, {'id': 97, 'text': '"Dorian! Before I knew you, acting was the only reality of my life," she cried, running to embrace him.', 'translation': '"Dorian! Seni tanımadan önce oyunculuk hayatımın tek gerçeğiydi," diye ona sarılmak için koşarak haykırdı.', 'notes': 'only reality: tek gerçek.'}, {'id': 98, 'text': '"Tonight, your love has awakened my real soul; how can I mimic fake passions upon a painted stage?"', 'translation': '"Bu gece senin aşkın gerçek ruhumu uyandırdı; boyalı bir sahnede sahte tutkuları artık nasıl taklit edebilirim ki?"', 'notes': 'mimic fake passions: sahte tutkuları taklit etmek.'}, {'id': 99, 'text': '"You have killed my love!" Dorian screamed brutally, throwing her violently onto the floor.', 'translation': '"Aşkımı öldürdün sen!" diye acımasızca haykırdı Dorian; onu şiddetle yere savurarak.', 'notes': 'killed my love: aşkımı öldürdün.'}, {'id': 100, 'text': '"You are shallow and worthless; you have ruined my artistic ideals, and I never wish to see your face again!"', 'translation': '"Sen sığ ve değersizsin; sanatsal ideallerimi yerle bir ettin ve yüzünü bir daha asla görmek istemiyorum!"', 'notes': 'artistic ideals: sanatsal idealler.'}]}, {'page_no': 6, 'title': 'The First Change in the Portrait', 'tr_title': 'Portredeki İlk Değişim', 'vocab_focus': [('remorse', 'vicdan azabı, pişmanlık'), ('sneer', 'alaycı sırıtış, küçümseme'), ('cruelty', 'zalimlik, acımasızlık'), ('canvas', 'tuval'), ('mirror', 'ayna'), ('conscience', 'vicdan'), ('prayer', 'dua'), ('amends', 'telafi, tazmin')], 'sentences': [{'id': 101, 'text': 'Dorian slammed the dressing room door behind him, leaving Sibyl weeping hysterically upon the bare wooden floor.', 'translation': "Dorian soyunma odasının kapısını arkasından çarparak kapattı ve Sibyl'ı çıplak tahta zeminde histerik şekilde ağlar halde bıraktı.", 'notes': 'bare wooden floor: çıplak tahta zemin.'}, {'id': 102, 'text': 'He walked through the dark, deserted streets of London until dawn, trying to calm his raging, wounded pride.', 'translation': "Öfkeyle kabaran, yaralı gururunu yatıştırmaya çalışarak şafak sökene dek Londra'nın karanlık ve ıssız sokaklarında yürüdü.", 'notes': 'wounded pride: yaralı gurur.'}, {'id': 103, 'text': 'When he arrived at his luxurious townhouse in Grosvenor Square, the morning sun was bathing the drawing-room in golden light.', 'translation': "Grosvenor Meydanı'ndaki lüks konağına vardığında sabah güneşi salonu altın bir ışıkla yıkıyordu.", 'notes': 'luxurious townhouse: lüks konak.'}, {'id': 104, 'text': "Walking past the easel where Basil's masterpiece stood, Dorian glanced casually at his painted likeness.", 'translation': "Basil'ın başyapıtının durduğu şövalenin yanından geçerken Dorian resmedilmiş suretine öylesine bir göz attı.", 'notes': 'painted likeness: resmedilmiş suret/benzerlik.'}, {'id': 105, 'text': 'He stopped dead in his tracks, staring at the canvas in frozen disbelief.', 'translation': 'Donuk bir inançsızlıkla tuvale bakakalarak olduğu yerde mıhlanıp kaldı.', 'notes': 'stopped dead in his tracks: olduğu yerde mıhlanıp kaldı.'}, {'id': 106, 'text': 'The expression on the painted face had altered in a subtle, unmistakable, and horrifying manner.', 'translation': 'Resmedilmiş yüzdeki ifade sinsi, inkâr edilemez ve korkunç bir biçimde değişmişti.', 'notes': 'altered in a subtle manner: sinsi/ince bir biçimde değişmiş.'}, {'id': 107, 'text': 'Around the beautiful scarlet mouth, there was a distinct, cruel sneer that had never been there before.', 'translation': 'O güzel kırmızı ağzın etrafında daha önce asla orada bulunmayan belirgin, zalimce bir sırıtış vardı.', 'notes': 'cruel sneer: zalimce sırıtış.'}, {'id': 108, 'text': 'He rubbed his eyes, thinking that the bright morning sunlight was creating a deceptive optical illusion.', 'translation': 'Parlak sabah güneşinin aldatıcı bir optik illüzyon yarattığını düşünerek gözlerini ovuşturdu.', 'notes': 'optical illusion: optik illüzyon/göz yanılması.'}, {'id': 109, 'text': 'He stepped closer, examining the brushstrokes with trembling fingers: the paint was dry, solid, and untouched.', 'translation': 'Daha da yaklaştı ve titreyen parmaklarla fırça darbelerini inceledi: Boya kuru, katı ve el değmemişti.', 'notes': 'untouched: el değmemiş.'}, {'id': 110, 'text': 'Yet there was no doubt: the face on the canvas was sneering with cold, unfeeling cruelty!', 'translation': 'Yine de hiç şüphe yoktu: Tuvaldeki yüz soğuk, duygusuz bir acımasızlıkla sırıtmaktaydı!', 'notes': 'unfeeling cruelty: duygusuz zalimlik.'}, {'id': 111, 'text': "Suddenly, with the force of a thunderclap, his memory flashed back to his passionate wish in Basil's studio.", 'translation': "Ansızın bir gök gürültüsü şiddetiyle hafızası Basil'ın atölyesindeki o tutkulu dileğine geri döndü.", 'notes': 'force of a thunderclap: gök gürültüsü şiddeti.'}, {'id': 112, 'text': '"If it were I who remained always young, and the picture that was to grow old! I would give my soul for that!"', 'translation': '"Keşke her zaman genç kalacak olan ben olsaydım ve yaşlanacak olan şu resim olsaydı! Bunun uğruna ruhumu verirdim!"', 'notes': 'give my soul: ruhumu vermek.'}, {'id': 113, 'text': 'Could it be that his prayer had been answered by some dark, supernatural power?', 'translation': 'Yoksa yakarışı karanlık, doğaüstü bir güç tarafından kabul mü edilmişti?', 'notes': 'prayer answered: duanın kabul edilmesi.'}, {'id': 114, 'text': 'Was this portrait destined to bear the moral burden of his sins, while his living flesh remained forever unblemished?', 'translation': 'Kendi yaşayan bedeni sonsuza dek lekesiz kalırken, bu portre günahlarının ahlaki yükünü taşımaya mı mahkûm edilmişti?', 'notes': 'forever unblemished: sonsuza dek lekesiz.'}, {'id': 115, 'text': 'A sickening sense of terror and shame washed over his troubled heart.', 'translation': 'Huzursuz yüreğini mide bulandırıcı bir dehşet ve utanç hissi kapladı.', 'notes': 'sickening sense of terror: mide bulandırıcı dehşet hissi.'}, {'id': 116, 'text': 'The picture would be a visual mirror of his conscience, reflecting every stain upon his immortal soul.', 'translation': 'Resim, vicdanının görsel bir aynası olacak ve ölümsüz ruhundaki her lekeyi yansıtacaktı.', 'notes': 'visual mirror: görsel ayna.'}, {'id': 117, 'text': 'He had been brutal to Sibyl Vane; he had crushed her innocent heart beneath his callous vanity.', 'translation': "Sibyl Vane'e karşı çok gaddar davranmıştı; onun masum kalbini taşlaşmış kibrinin altında ezmişti.", 'notes': 'callous vanity: taşlaşmış kibir.'}, {'id': 118, 'text': '"I will resist temptation; I will make amends!" Dorian vowed aloud, weeping in sincere remorse.', 'translation': '"Günaha direneceğim; hatamı telafi edeceğim!" diye yüksek sesle ant içti Dorian, samimi bir pişmanlıkla ağlayarak.', 'notes': 'make amends: telafi etmek.'}, {'id': 119, 'text': '"I will return to Sibyl, beg on my knees for her forgiveness, and marry her without delay!"', 'translation': '"Sibyl\'a döneceğim, dizlerimin üstünde af dileyeceğim ve onunla gecikmeksizin evleneceğim!"', 'notes': 'beg on my knees: dizlerimin üstünde yalvarmak.'}, {'id': 120, 'text': 'Comforted by this noble resolution, he draped a heavy silk screen over the portrait to hide the sneering mouth.', 'translation': 'Bu asil kararla teselli bularak, sırıtan ağzı gizlemek için portrenin üzerine ağır ipek bir paravan örttü.', 'notes': 'draped heavy screen: ağır paravan örttü.'}]}, {'page_no': 7, 'title': "Sibyl's Suicide and the Yellow Book", 'tr_title': "Sibyl'ın İntiharı ve Sarı Kapaklı Kitap", 'vocab_focus': [('inquest', 'ölüm tahkikatı'), ('poison', 'zehir'), ('hedonism', 'hazcılık, hedonizm'), ('spectator', 'seyirci, izleyici'), ('decadence', 'çöküş, ahlaki yozlaşma'), ('novel', 'roman'), ('corruption', 'yozlaşma, bozulma'), ('indifference', 'kayıtsızlık, umursamazlık')], 'sentences': [{'id': 121, 'text': 'The next afternoon, Dorian sat at his writing table and composed a passionate, eight-page letter of apology to Sibyl.', 'translation': "Ertesi öğleden sonra Dorian yazı masasına oturdu ve Sibyl'a sekiz sayfalık tutkulu bir özür mektubu kaleme aldı.", 'notes': 'letter of apology: özür mektubu.'}, {'id': 122, 'text': 'He covered the pages with frantic promises of love, begging her to forgive his madness and become his wife.', 'translation': 'Deliliğini bağışlaması ve karısı olması için yalvararak sayfaları çılgınca aşk vaatleriyle doldurdu.', 'notes': 'frantic promises: çılgınca vaatler.'}, {'id': 123, 'text': 'Just as he sealed the envelope, a knock sounded and Lord Henry stepped into the library.', 'translation': 'Tam zarfı mühürlemişti ki kapı çalındı ve Lord Henry kütüphaneye adım attı.', 'notes': 'knock sounded: kapı çalındı.'}, {'id': 124, 'text': '"My dear Dorian, I am so sorry for everything," Lord Henry began gravely; "you must not think too much about it."', 'translation': '"Sevgili Dorian, her şey için çok üzgünüm," diye ciddiyetle başladı Lord Henry; "bu konuda fazla düşünmemelisin."', 'notes': 'began gravely: ciddiyetle başladı.'}, {'id': 125, 'text': '"You mean about my cruelty to Sibyl?" Dorian replied eagerly; "I have already resolved to make full amends!"', 'translation': '"Sibyl\'a yaptığım zalimliği mi kastediyorsun?" diye hevesle yanıtladı Dorian; "Bunu tamamen telafi etmeye çoktan karar verdim!"', 'notes': 'resolved to make amends: telafi etmeye karar verdi.'}, {'id': 126, 'text': '"I am going to marry her, Harry; our marriage will be the beginning of a pure and noble life!"', 'translation': '"Onunla evleneceğim Harry; evliliğimiz saf ve asil bir hayatın başlangıcı olacak!"', 'notes': 'pure and noble life: saf ve asil bir yaşam.'}, {'id': 127, 'text': 'Lord Henry looked at him with profound shock: "Dorian, did you not receive my telegram this morning?"', 'translation': 'Lord Henry derin bir şokla ona baktı: "Dorian, bu sabah çektiğim telgrafı almadın mı?"', 'notes': 'receive telegram: telgrafı almak.'}, {'id': 128, 'text': '"No; what has happened? Speak, Harry!" Dorian cried, seizing Lord Henry\'s arm.', 'translation': '"Hayır; ne oldu? Konuş Harry!" diye haykırdı Dorian Lord Henry\'nin kolunu kavrayarak.', 'notes': 'seizing arm: kolunu kavrayarak.'}, {'id': 129, 'text': '"Sibyl Vane is dead," Lord Henry said softly.', 'translation': '"Sibyl Vane öldü," dedi Lord Henry usulca.', 'notes': 'said softly: usulca söyledi.'}, {'id': 130, 'text': '"Dead! It is a lie!" Dorian screamed, reeling backward as if struck by a physical blow.', 'translation': '"Öldü mü! Bu bir yalan!" diye haykırdı Dorian, sanki fiziksel bir darbe almış gibi geriye sendelerken.', 'notes': 'reeling backward: geriye doğru sendelemek.'}, {'id': 131, 'text': '"It is horribly true; she swallowed prussic acid in the cloakroom after you left her and died instantly."', 'translation': '"Korkunç ama doğru; sen onu terk ettikten sonra vestiyerde prusik asit yutmuş ve anında can vermiş."', 'notes': 'swallowed acid: asit yuttu.'}, {'id': 132, 'text': 'Dorian covered his face and wept bitter tears of grief: "I have murdered her as surely as if I had cut her throat!"', 'translation': 'Dorian yüzünü kapattı ve acı keder gözyaşları döktü: "Boğazını kesmişim gibi onu kesin olarak ben öldürdüm!"', 'notes': 'wept bitter tears: acı gözyaşları döktü.'}, {'id': 133, 'text': 'Lord Henry sat beside him, soothing the young man with poisonous, seductive philosophical sophistry.', 'translation': 'Lord Henry yanına oturdu ve zehirli, baştan çıkarıcı felsefi safsatalarla genç adamı teskin etti.', 'notes': 'seductive sophistry: baştan çıkarıcı safsata.'}, {'id': 134, 'text': '"Do not waste your tears, Dorian; think of it as a magnificent Greek tragedy, not a vulgar crime."', 'translation': '"Gözyaşlarını heba etme Dorian; bunu bayağı bir suç olarak değil, muhteşem bir Grek trajedisi olarak düşün."', 'notes': 'waste tears: gözyaşlarını heba etmek.'}, {'id': 135, 'text': '"She lived as an artist, and she died for love upon the altar of romance; her death was her finest performance."', 'translation': '"O bir sanatçı olarak yaşadı ve aşk için romantizmin sunağında öldü; ölümü onun en harika performansıydı."', 'notes': 'altar of romance: romantizmin sunağı.'}, {'id': 136, 'text': "The poisonous words acted like sweet opium upon Dorian's impressionable, selfish soul.", 'translation': "O zehirli kelimeler Dorian'ın kolay etkilenen, bencil ruhunda tatlı bir afyon gibi etki yaptı.", 'notes': 'sweet opium: tatlı afyon.'}, {'id': 137, 'text': 'By evening, his grief had vanished completely, and he accompanied Lord Henry to the opera as if nothing had occurred.', 'translation': 'Akşama doğru kederi tamamen yok olmuştu ve sanki hiçbir şey yaşanmamış gibi Lord Henry ile operaya gitti.', 'notes': 'grief had vanished: kederi yok olmuştu.'}, {'id': 138, 'text': 'Before parting that night, Lord Henry presented Dorian with a curious French novel bound in a yellow paper cover.', 'translation': "O gece ayrılmadan önce Lord Henry Dorian'a sarı kağıt kapaklı ilginç bir Fransız romanı hediye etti.", 'notes': 'yellow paper cover: sarı kağıt kapak.'}, {'id': 139, 'text': 'The book described the decadent life of a Parisian aristocrat who pursued all strange, forbidden sensory pleasures.', 'translation': 'Kitap tüm tuhaf, yasak duyusal hazların peşinde koşan Parisli bir aristokratın yozlaşmış hayatını anlatıyordu.', 'notes': 'forbidden pleasures: yasak hazlar.'}, {'id': 140, 'text': "This infamous 'Yellow Book' was destined to poison Dorian's mind and guide him down the path of moral ruin.", 'translation': "Bu meşum 'Sarı Kitap' Dorian'ın zihnini zehirlemeye ve onu ahlaki yıkımın yoluna sokmaya mahkûmdu.", 'notes': 'path of moral ruin: ahlaki yıkım yolu.'}]}, {'page_no': 8, 'title': 'Hiding the Picture in the Old Schoolroom', 'tr_title': 'Resmi Eski Okul Odasına Gizlemek', 'vocab_focus': [('schoolroom', 'okul odası, derslik'), ('attic', 'tavan arası'), ('tapestry', 'duvar halısı'), ('frame-maker', 'çerçeveci'), ('padlock', 'asma kilit'), ('sanctuary', 'sığınak, gizli yer'), ('indifference', 'kayıtsızlık'), ('decay', 'çürüme, bozulma')], 'sentences': [{'id': 141, 'text': "The following morning, Basil Hallward called at the house to offer his condolences regarding Sibyl's tragic death.", 'translation': "Ertesi sabah Basil Hallward Sibyl'ın trajik ölümüyle ilgili taziyelerini sunmak için eve uğradı.", 'notes': 'offer condolences: taziyelerini sunmak.'}, {'id': 142, 'text': "To Basil's utter horror, he found Dorian perfectly calm, sipping iced tea and discussing French literature.", 'translation': "Basil büyük bir dehşetle Dorian'ı gayet sakin, buzlu çayını yudumlarken ve Fransız edebiyatını tartışırken buldu.", 'notes': 'utter horror: büyük dehşet.'}, {'id': 143, 'text': '"Dorian, how can you speak so callously? Yesterday, the girl you loved poisoned herself!" Basil cried in dismay.', 'translation': '"Dorian nasıl bu kadar duygusuzca konuşabiliyorsun? Dün sevdiğin kız kendini zehirledi!" diye haykırdı Basil dehşetle.', 'notes': 'speak so callously: bu kadar duygusuzca konuşmak.'}, {'id': 144, 'text': '"What is done is done; what is past is past," Dorian replied coldly, repeating Lord Henry\'s cynical maxims.', 'translation': '"Olan oldu; geçmiş geçmişte kaldı," diye soğukça yanıtladı Dorian, Lord Henry\'nin alaycı vecizelerini tekrarlayarak.', 'notes': 'what is done is done: olan oldu.'}, {'id': 145, 'text': 'Basil then asked to view the portrait, explaining that he wished to exhibit it at a prestigious salon in Paris.', 'translation': "Ardından Basil portreyi görmek istedi ve onu Paris'teki prestijli bir salonda sergilemek istediğini açıkladı.", 'notes': 'prestigious salon: prestijli salon/sergi.'}, {'id': 146, 'text': 'Dorian leaped from his chair in a frenzy of terror, guarding the screen with outstretched arms.', 'translation': 'Dorian dehşet dolu bir panikle koltuğundan fırladı ve kollarını açarak paravanı korudu.', 'notes': 'frenzy of terror: dehşet dolu panik.'}, {'id': 147, 'text': '"You shall never look upon it again, Basil! If you touch that screen, I will never speak to you as long as I live!"', 'translation': '"Ona bir daha asla bakmayacaksın Basil! Eğer o paravana dokunursan yaşadığım sürece seninle bir daha konuşmam!"', 'notes': 'never look upon it: ona bir daha asla bakmamak.'}, {'id': 148, 'text': "Perplexed and deeply hurt by Dorian's irrational rage, the gentle painter sadly bade farewell and departed.", 'translation': "Dorian'ın bu mantıksız öfkesiyle şaşkına dönen ve derinden kırılan nazik ressam üzüntüyle veda edip ayrıldı.", 'notes': 'bade farewell: veda etti.'}, {'id': 149, 'text': 'As soon as Basil was gone, Dorian knew he must conceal the supernatural canvas immediately.', 'translation': 'Basil gider gitmez Dorian o doğaüstü tuvali derhal gizlemesi gerektiğini anladı.', 'notes': 'conceal immediately: derhal gizlemek.'}, {'id': 150, 'text': 'If a servant should glance behind the screen, the monstrous secret of his changing face would be exposed to the world.', 'translation': 'Eğer bir uşak paravanın arkasına bir göz atacak olursa değişen yüzünün o canavarca sırrı dünyaya ifşa olurdu.', 'notes': 'glance behind the screen: paravanın arkasına bakmak.'}, {'id': 151, 'text': 'He decided to hide the portrait in the old schoolroom at the top of the house, built by his grandfather.', 'translation': 'Portreyi evin en üst katında, büyükbabası tarafından yaptırılmış olan eski okul odasına saklamaya karar verdi.', 'notes': 'old schoolroom: eski derslik/okul odası.'}, {'id': 152, 'text': 'The room had been locked for years, containing only forgotten books, discarded toys, and dusty furniture.', 'translation': 'Oda yıllardır kilitliydi; içinde yalnızca unutulmuş kitaplar, atılmış oyuncaklar ve tozlu mobilyalar vardı.', 'notes': 'discarded toys: atılmış oyuncaklar.'}, {'id': 153, 'text': 'He summoned two burly frame-makers from South Audley Street to transport the heavy painting upstairs.', 'translation': "Ağır tabloyu yukarı taşımak için South Audley Sokağı'ndan iki iri yarı çerçeveci çağırdı.", 'notes': 'burly frame-makers: iri yarı çerçeveciler.'}, {'id': 154, 'text': 'Dorian covered the canvas with a large purple satin pall, heavily embroidered with gold thread.', 'translation': 'Dorian tuvali altın iple ağır şekilde işlenmiş büyük mor saten bir örtüyle kapattı.', 'notes': 'embroidered with gold: altınla işlenmiş.'}, {'id': 155, 'text': 'The workmen hoisted the heavy frame and carried it carefully up the winding stairs to the attic.', 'translation': 'İşçiler ağır çerçeveyi kaldırdılar ve dikkatlice döner merdivenlerden çatı katına taşıdılar.', 'notes': 'winding stairs: döner merdivenler.'}, {'id': 156, 'text': 'Once inside the abandoned schoolroom, Dorian paid the men generously and dismissed them from the house.', 'translation': 'Terk edilmiş okul odasına girdikten sonra Dorian adamlara cömertçe ödeme yaptı ve onları evden yolladı.', 'notes': 'dismissed from the house: evden yolladı.'}, {'id': 157, 'text': 'He locked the heavy oak door with his own brass key, dropping it into his waistcoat pocket.', 'translation': 'Ağır meşe kapıyı kendi pirinç anahtarıyla kilitledi ve anahtarı yelek cebine attı.', 'notes': 'waistcoat pocket: yelek cebi.'}, {'id': 158, 'text': 'No human eye would ever enter this room; no living soul would ever behold the hideous painted decay.', 'translation': 'Bu odaya hiçbir insan gözü asla girmeyecekti; yaşayan hiçbir can o korkunç resmedilmiş çürümeyi asla görmeyecekti.', 'notes': 'hideous painted decay: korkunç resmedilmiş çürüme.'}, {'id': 159, 'text': 'Here, in the dark solitude of the attic, the portrait would bear the festering marks of his shameful sins.', 'translation': 'Burada, tavan arasının karanlık yalnızlığında portre, onun utanç verici günahlarının irinli izlerini taşıyacaktı.', 'notes': 'festering marks: irinli/cerahatli izler.'}, {'id': 160, 'text': 'Meanwhile, Dorian Gray would walk through the gilded salons of London, radiant with perpetual, untouchable youth.', 'translation': "Bu esnada Dorian Gray, ebedi ve dokunulmaz bir gençlikle ışıldayarak Londra'nın yaldızlı salonlarında salınacaktı.", 'notes': 'perpetual untouchable youth: ebedi ve dokunulmaz gençlik.'}]}, {'page_no': 9, 'title': 'Years of Hedonism and the Poisonous Book', 'tr_title': 'Yıllar Süren Haz Düşkünlüğü ve Zehirli Kitap', 'vocab_focus': [('hedonism', 'hazcılık, zevk düşkünlüğü'), ('influence', 'etki, tesir'), ('tapestry', 'duvar halısı'), ('ecclesiastical', 'kiliseye ait, ruhban'), ('perfume', 'parfüm, koku'), ('unblemished', 'lekesiz, tertemiz'), ('corruption', 'yozlaşma, ahlaki çöküş'), ('dual', 'ikili, çift taraflı')], 'sentences': [{'id': 161, 'text': 'For years, Dorian Gray lived under the intoxicating influence of the yellow French novel sent by Lord Henry.', 'translation': 'Yıllar boyunca Dorian Gray, Lord Henry tarafından gönderilen sarı kapaklı Fransız romanının sarhoş edici etkisi altında yaşadı.', 'notes': 'intoxicating influence: sarhoş edici etki.'}, {'id': 162, 'text': 'He purchased numerous copies of the book, having them bound in diverse colors to match his varying moods.', 'translation': 'Değişen ruh hallerine uysun diye kitabın pek çok kopyasını satın alıp farklı renklerde ciltletti.', 'notes': 'varying moods: değişen ruh halleri.'}, {'id': 163, 'text': 'The hero of the novel became to Dorian a kind of prefiguration of his own strange, secret existence.', 'translation': 'Romanın kahramanı, Dorian için kendi tuhaf ve gizli varoluşunun adeta bir ön habercisi haline geldi.', 'notes': 'strange existence: tuhaf varoluş.'}, {'id': 164, 'text': 'Dorian sought to create a new hedonism that would satisfy every curiosity of the senses and the intellect.', 'translation': 'Dorian, duyuların ve zekanın her türlü merakını tatmin edecek yeni bir hazcılık anlayışı yaratmaya çalıştı.', 'notes': 'new hedonism: yeni hazcılık.'}, {'id': 165, 'text': 'He devoted whole seasons to the study of rare perfumes, distilling sweet scents from exotic Eastern flowers.', 'translation': 'Tüm mevsimlerini egzotik Doğu çiçeklerinden tatlı kokular damıtarak nadir parfümleri incelemeye adadı.', 'notes': 'devoted whole seasons: bütün mevsimlerini adadı.'}, {'id': 166, 'text': 'At other times, he became fascinated by jewels, collecting fiery rubies, cool sapphires, and lustrous pearls.', 'translation': 'Kimi zaman da mücevherlere merak sardı; alev alev parlayan yakutlar, soğuk safirler ve ışıltılı inciler biriktirdi.', 'notes': 'fascinated by jewels: mücevherlere büyülenmiş.'}, {'id': 167, 'text': 'He amassed magnificent antique embroideries and heavy church vestments woven with gold and precious stones.', 'translation': 'Altın ve değerli taşlarla dokunmuş muhteşem antika işlemeler ve ağır kilise cüppeleri topladı.', 'notes': 'amassed vestments: cüppeler topladı/biriktirdi.'}, {'id': 168, 'text': 'Yet despite these artistic passions, his real preoccupation was the hidden portrait in the locked schoolroom.', 'translation': 'Fakat bu sanatsal tutkularına rağmen, asıl meşguliyeti kilitli okul odasındaki gizli portreydi.', 'notes': 'real preoccupation: asıl meşguliyet.'}, {'id': 169, 'text': 'Frequently, he crept upstairs at midnight to gaze upon the decaying face that was bearing all his sins.', 'translation': 'Sık sık gece yarısı yukarı süzülerek tüm günahlarını sırtlanan o çürüyen çehreye dik dik bakardı.', 'notes': 'bearing all sins: tüm günahları taşıyan.'}, {'id': 170, 'text': 'He would hold a small silver mirror beside the canvas, comparing his unlined countenance with the painted horror.', 'translation': 'Tuvalin yanına küçük gümüş bir ayna tutar, kırışıksız çehresini resmedilmiş dehşetle kıyaslardı.', 'notes': 'unlined countenance: kırışıksız çehre.'}, {'id': 171, 'text': 'He felt a monstrous, chilling joy in knowing that his physical body was completely immune to aging.', 'translation': 'Fiziksel bedeninin yaşlanmaya karşı tamamen bağışık olduğunu bilmekten canavarca ve ürpertici bir haz duyuyordu.', 'notes': 'immune to aging: yaşlanmaya karşı bağışık.'}, {'id': 172, 'text': 'Every year that passed carved deeper trenches of wickedness upon the canvas, leaving Dorian himself untouched.', 'translation': "Geçen her yıl tuvalin üzerine daha derin kötülük izleri kazıyor, Dorian'ın bizzat kendisine ise hiç dokunmuyordu.", 'notes': 'carved deeper trenches: daha derin oluklar/izler kazdı.'}, {'id': 173, 'text': 'At thirty-two years of age, he possessed the same dewy freshness and youthful innocence of an undergraduate.', 'translation': 'Otuz iki yaşında bile bir üniversite öğrencisinin o taze duruluğuna ve gençlik masumiyetine sahipti.', 'notes': 'dewy freshness: taze duruluk.'}, {'id': 174, 'text': 'Society was enchanted by his graceful manners, his exquisite taste, and his unfading charm.', 'translation': 'Sosyete onun zarif tavırlarına, kusursuz zevkine ve solmayan cazibesine hayran kalmıştı.', 'notes': 'unfading charm: solmayan cazibe.'}, {'id': 175, 'text': 'Young men copied his neckties, imitated his speech, and attempted to adopt his fashionable disdain.', 'translation': 'Genç adamlar onun kravatlarını taklit eder, konuşmasını yineler ve modaya uygun kibrini benimsemeye çalışırdı.', 'notes': 'fashionable disdain: modaya uygun kibir/küçümseme.'}, {'id': 176, 'text': 'However, dark and ugly whispers began to circulate about his secret nocturnal journeys into disreputable quarters.', 'translation': 'Ne var ki, saygın olmayan mahallelere yaptığı gizli gece yolculukları hakkında karanlık ve çirkin fısıltılar dolaşmaya başladı.', 'notes': 'nocturnal journeys: gece yolculukları.'}, {'id': 177, 'text': 'He was seen frequenting wretched taverns and foggy alleys where no respectable gentleman ever ventured.', 'translation': 'Hiçbir saygın beyefendinin ayak basmadığı sefil meyhanelere ve sisli ara sokaklara sık sık uğrarken görülüyordu.', 'notes': 'respectable gentleman: saygın beyefendi.'}, {'id': 178, 'text': 'He began to lead a double existence, moving between refined drawing rooms and sordid criminal dens.', 'translation': 'Zarif salonlar ile pespaye suç inleri arasında mekik dokuyarak çifte bir yaşam sürdürmeye başladı.', 'notes': 'double existence: ikili yaşam/varoluş.'}, {'id': 179, 'text': 'The purity of his face seemed to everyone an absolute guarantee of the purity of his spirit.', 'translation': 'Yüzünün saf masumiyeti herkese ruhunun saflığının kesin bir teminatı gibi geliyordu.', 'notes': 'absolute guarantee: kesin teminat.'}, {'id': 180, 'text': 'None suspected that behind that angelic countenance lurked a rotting soul consumed by moral corruption.', 'translation': 'O melek gibi çehrenin ardında ahlaki yozlaşmayla tükenmiş çürüyen bir ruhun gizlendiğinden hiç kimse kuşkulanmıyordu.', 'notes': 'moral corruption: ahlaki yozlaşma.'}]}, {'page_no': 10, 'title': 'Whispers of Scandal and Ruined Reputations', 'tr_title': 'Skandal Fısıltıları ve Mahvolan İtibarlar', 'vocab_focus': [('scandal', 'rezalet, skandal'), ('ostracism', 'toplumdan dışlama, aforoz'), ('aristocracy', 'aristokrasi, soylular sınıfı'), ('whisper', 'fısıltı, dedikodu'), ('ruin', 'mahvetmek, batırmak'), ('innocence', 'masumiyet'), ('hypocrite', 'ikiyüzlü kimse'), ('reputation', 'itibar, şöhret')], 'sentences': [{'id': 181, 'text': 'As the years advanced, scandalous stories regarding Dorian Gray accumulated throughout the aristocratic circles of London.', 'translation': "Yıllar ilerledikçe Dorian Gray ile ilgili skandal hikayeler Londra'nın aristokrat çevrelerinde birikip durdu.", 'notes': 'aristocratic circles: aristokrat çevreler.'}, {'id': 182, 'text': 'Mothers warned their sons against his company, calling him a dangerous corrupter of young men.', 'translation': 'Anneler oğullarını onun arkadaşlığına karşı uyarır, onu genç erkekleri yoldan çıkaran tehlikeli biri olarak anarlardı.', 'notes': 'corrupter of men: insanları yoldan çıkaran.'}, {'id': 183, 'text': 'Members of prominent London clubs stood up and walked silently from the room whenever Dorian entered.', 'translation': 'Seçkin Londra kulüplerinin üyeleri, Dorian içeri her girdiğinde sessizce ayağa kalkıp odayı terk ederdi.', 'notes': 'walked silently: sessizce yürüdü/çıktı.'}, {'id': 184, 'text': 'A distinguished young duke left the card table in disgust rather than sit opposite his once beloved friend.', 'translation': 'Seçkin bir genç dük, bir zamanlar çok sevdiği dostunun karşısına oturmaktansa tiksintiyle kumar masasını terk etti.', 'notes': 'in disgust: tiksintiyle.'}, {'id': 185, 'text': 'Several promising young officers who had shared his intimate confidence ended their careers in public disgrace.', 'translation': 'Onunla en mahrem sırlarını paylaşmış olan birkaç umut vadeden genç subay kariyerlerini kamuya açık bir rezaletle noktaladı.', 'notes': 'public disgrace: aleni rezalet.'}, {'id': 186, 'text': 'One young poet, whose mind had once been bright and noble, committed suicide in a miserable garret.', 'translation': 'Zihni bir zamanlar parlak ve asil olan genç bir şair sefil bir tavan arasında intihar etti.', 'notes': 'committed suicide: intihar etti.'}, {'id': 187, 'text': 'Another youthful gentleman was compelled to flee the country after a ruinous gambling scandal in which Dorian was implicated.', 'translation': "Bir başka genç beyefendi, Dorian'ın da adının karıştığı yıkıcı bir kumar skandalından sonra ülkeyi terk etmek zorunda kaldı.", 'notes': 'compelled to flee: kaçmak zorunda kaldı.'}, {'id': 188, 'text': "Lady Gwendolen, Lord Henry's sister, lost her name and social standing entirely after her association with him.", 'translation': "Lord Henry'nin kız kardeşi Lady Gwendolen, onunla olan yakınlığından sonra adını ve sosyal konumunu tamamen kaybetti.", 'notes': 'social standing: sosyal konum/itibar.'}, {'id': 189, 'text': 'Women turned deathly pale when Dorian crossed the threshold of fashionable ballrooms in Mayfair.', 'translation': "Dorian, Mayfair'deki sosyetik balo salonlarının eşiğinden adım attığında kadınların beti benzi atardı.", 'notes': 'crossed threshold: eşikten adım attı.'}, {'id': 190, 'text': 'Yet when people looked directly into his bright blue eyes, all suspicions seemed to dissolve into nothingness.', 'translation': 'Yine de insanlar doğrudan onun parlak mavi gözlerine baktıklarında bütün kuşkular sanki yok olup giderdi.', 'notes': 'dissolve into nothingness: yok olup gitmek.'}, {'id': 191, 'text': '"How could anyone so genuinely beautiful commit the vile atrocities ascribed to him?" society wondered.', 'translation': '"Böylesine sahiden güzel biri kendisine atfedilen o alçakça rezillikleri nasıl işleyebilir ki?" diye merak ederdi sosyete.', 'notes': 'vile atrocities: alçakça vahşetler/kötülükler.'}, {'id': 192, 'text': 'Lord Henry merely smiled at the gossip, remarking that scandal was the tribute ordinary people paid to beauty.', 'translation': 'Lord Henry dedikodulara yalnızca gülümser, skandalın sıradan insanların güzelliğe ödediği bir haraç olduğunu söylerdi.', 'notes': 'tribute to beauty: güzelliğe haraç/övgü.'}, {'id': 193, 'text': 'Dorian smiled back, but in his secret heart, a gnawing anxiety tormented him day and night.', 'translation': 'Dorian da karşılık vererek gülümsedi fakat gizli kalbinde kemirici bir endişe gece gündüz ona azap çektiriyordu.', 'notes': 'gnawing anxiety: kemirici endişe.'}, {'id': 194, 'text': 'He lived in perpetual dread that some inquisitive servant might pick the lock of the schoolroom.', 'translation': 'Meraklı bir hizmetkarın okul odasının kilidini açabileceği yönündeki daimi bir dehşet içinde yaşıyordu.', 'notes': 'perpetual dread: daimi dehşet/korku.'}, {'id': 195, 'text': 'Whenever he traveled to his country house, he worried obsessively about what might happen in his absence.', 'translation': 'Kır evine her gittiğinde, yokluğunda neler olabileceği konusunda takıntılı bir biçimde endişelenirdi.', 'notes': 'worried obsessively: takıntılı şekilde endişelendi.'}, {'id': 196, 'text': 'He began to distrust everyone around him, suspecting that his loyal valet Victor was spying on his movements.', 'translation': "Çevresindeki herkesten kuşkulanmaya başladı; sadık uşağı Victor'ın hareketlerini gözetlediğinden şüpheleniyordu.", 'notes': 'spying on movements: hareketlerini gözetlemek.'}, {'id': 197, 'text': 'He had the heavy iron door reinforced with a new and complicated brass padlock of foreign manufacture.', 'translation': 'Ağır demir kapıyı yabancı yapım yeni ve karmaşık bir pirinç asma kilitle takviye ettirdi.', 'notes': 'brass padlock: pirinç asma kilit.'}, {'id': 198, 'text': 'The key never left his possession; it was attached to a gold chain around his neck beneath his shirt.', 'translation': 'Anahtar yanından hiç ayrılmazdı; gömleğinin altında boynundaki altın bir zincire takılı dururdu.', 'notes': 'left his possession: zilyetliğinden/yanından ayrıldı.'}, {'id': 199, 'text': 'He was a prisoner of his own dreadful secret, tethered forever to the painted record of his soul.', 'translation': 'Kendi korkunç sırrının bir tutsağıydı; ruhunun resmedilmiş kaydına sonsuza kadar prangalanmıştı.', 'notes': 'tethered forever: sonsuza dek prangalanmış.'}, {'id': 200, 'text': 'Thus the years drifted away until Dorian approached his thirty-eighth birthday on a bitter, icy winter.', 'translation': 'Böylece yıllar akıp gitti ta ki Dorian dondurucu, buz gibi bir kış mevsiminde otuz sekizinci yaşına yaklaşana dek.', 'notes': 'years drifted away: yıllar akıp gitti.'}]}, {'page_no': 11, 'title': "Basil Hallward's Midnight Visit", 'tr_title': "Basil Hallward'ın Gece Yarısı Ziyareti", 'vocab_focus': [('departure', 'ayrılış, kalkış'), ('companion', 'yoldaş, arkadaş'), ('heavy coat', 'kalın palto'), ('luggage', 'bavul, bagaj'), ('midnight', 'gece yarısı'), ('urgent', 'acil, ivedi'), ('farewell', 'veda'), ('appointment', 'randevu, buluşma')], 'sentences': [{'id': 201, 'text': 'It was on the ninth of November, the eve of his thirty-eighth birthday, that Dorian met his fate.', 'translation': "Dorian'ın kaderiyle karşılaştığı gün, otuz sekizinci yaş gününün arifesi olan dokuz Kasım günüydü.", 'notes': 'eve of his birthday: doğum gününün arifesi.'}, {'id': 202, 'text': "Dorian was walking home from Lord Henry's residence at eleven o'clock wrapped warmly in heavy furs.", 'translation': "Dorian saat on birde kalın kürklere sıkıca sarınmış halde Lord Henry'nin evinden evine doğru yürüyordu.", 'notes': 'wrapped in furs: kürklere sarınmış.'}, {'id': 203, 'text': 'A thick, yellowish fog had settled heavily over the gas-lit streets of London, muffling all footsteps.', 'translation': "Yoğun, sarımtırak bir sis Londra'nın gaz lambalı sokaklarına çökmüş, bütün ayak seslerini boğuklaştırıyordu.", 'notes': 'muffling all footsteps: bütün ayak seslerini boğan.'}, {'id': 204, 'text': 'As he approached the doorstep of his mansion, a cloaked figure stepped forward from the chilly mist.', 'translation': 'Malikanesinin kapı eşiğine yaklaştığı sırada pelerinli bir siluet ayaz sisin içinden öne doğru adım attı.', 'notes': 'cloaked figure: pelerinli siluet.'}, {'id': 205, 'text': '"Dorian! I have been waiting for you for nearly an hour," a familiar, grave voice called out.', 'translation': '"Dorian! Neredeyse bir saattir seni bekliyorum," diye tanıdık, ağırbaşlı bir ses seslendi.', 'notes': 'familiar grave voice: tanıdık ağırbaşlı ses.'}, {'id': 206, 'text': 'Dorian turned around in surprise and recognized Basil Hallward, his collar turned up against the cold.', 'translation': "Dorian şaşkınlıkla arkasını döndü ve yakasını soğuğa karşı kaldırmış olan Basil Hallward'ı tanıdı.", 'notes': 'collar turned up: yakası yukarı kaldırılmış.'}, {'id': 207, 'text': '"My dear Basil! What brings you out on such a wretched, freezing night?" Dorian asked casually.', 'translation': '"Sevgili Basil! Böylesine berbat ve dondurucu bir gecede seni dışarı çıkaran nedir?" diye sordu Dorian kayıtsızca.', 'notes': 'wretched freezing night: berbat dondurucu gece.'}, {'id': 208, 'text': '"I am leaving for Paris on the midnight train," Basil explained, pointing toward a four-wheeler cab holding his luggage.', 'translation': '"Gece yarısı treniyle Paris\'e gidiyorum," diye açıkladı Basil, bavullarını taşıyan dört tekerlekli faytonu işaret ederek.', 'notes': 'midnight train: gece yarısı treni.'}, {'id': 209, 'text': '"I intend to take a studio in France and work abroad for at least six months without interruption."', 'translation': '"Fransa\'da bir atölye tutup en az altı ay boyunca kesintisiz olarak yurt dışında çalışmaya niyetliyim."', 'notes': 'without interruption: kesintisiz.'}, {'id': 210, 'text': '"I could not leave England without speaking to you first; there are urgent matters we must discuss."', 'translation': '"Önce seninle konuşmadan İngiltere\'den ayrılamazdım; görüşmemiz gereken çok acil meseleler var."', 'notes': 'urgent matters: acil meseleler.'}, {'id': 211, 'text': 'Dorian felt a momentary tremor of apprehension, but he maintained a calm and courteous exterior.', 'translation': 'Dorian bir anlık ürpertici bir tedirginlik hissetti fakat sakin ve nazik görünüşünü korudu.', 'notes': 'tremor of apprehension: endişe ürpertisi.'}, {'id': 212, 'text': '"Come inside, then, Basil; you must not stand out in this dreadful fog," Dorian replied smoothly.', 'translation': '"İçeri gel o halde Basil; bu korkunç sisin içinde dışarıda dikilmemelisin," diye tatlı dille yanıt verdi Dorian.', 'notes': 'replied smoothly: tatlı dille/rahatça yanıtladı.'}, {'id': 213, 'text': 'He produced his latchkey, opened the heavy entrance door, and guided the painter into the warm, illuminated hall.', 'translation': 'Kapı anahtarını çıkardı, ağır giriş kapısını açtı ve ressamı sıcak, aydınlatılmış salona yönlendirdi.', 'notes': 'produced latchkey: kapı anahtarını çıkardı.'}, {'id': 214, 'text': 'A roaring wood fire burned merrily in the library hearth, casting long, dancing shadows across the leather armchairs.', 'translation': 'Kütüphane şöminesinde neşeyle gürül gürül bir odun ateşi yanıyor, deri koltukların üzerine uzun, dans eden gölgeler düşürüyordu.', 'notes': 'roaring fire: gürül gürül yanan ateş.'}, {'id': 215, 'text': 'Basil took off his heavy winter ulster and dropped it upon an oak table beside his damp hat.', 'translation': 'Basil kalın kışlık paltosunu çıkardı ve nemli şapkasının yanındaki meşe bir masanın üzerine bıraktı.', 'notes': 'heavy ulster: kalın kışlık palto.'}, {'id': 216, 'text': 'He stood by the mantelpiece, looking intently at Dorian with an expression of mingled sorrow and bewilderment.', 'translation': "Şömine rafının yanında durdu; keder ve şaşkınlığın birbirine karıştığı bir ifadeyle dikkatle Dorian'a baktı.", 'notes': 'mingled sorrow: birbirine karışmış keder.'}, {'id': 217, 'text': '"Dorian, you look exactly the same as you did the morning I first sketched your portrait in my studio,"', 'translation': '"Dorian, atölyemde portreni ilk çizdiğim o sabahki halinle tamamen aynı görünüyorsun,"', 'notes': 'first sketched: ilk kez eskizini çizdiğim.'}, {'id': 218, 'text': '"Nearly sixteen years have passed, yet not a single line has appeared upon your smooth forehead."', 'translation': '"Neredeyse on altı yıl geçti ama o pürüzsüz alnında tek bir çizgi dahi belirmedi."', 'notes': 'smooth forehead: pürüzsüz alın.'}, {'id': 219, 'text': 'Dorian laughed lightly, though his fingers tightened secretly around the cigarette holder he was holding.', 'translation': 'Dorian hafifçe güldü, her ne kadar parmakları tuttuğu sigara ağızlığının etrafında gizlice sıkılaşsa da.', 'notes': 'tightened secretly: gizlice sıkılaştı.'}, {'id': 220, 'text': '"Is that such a dreadful crime, Basil? You sound as if my youth were an insult to you!"', 'translation': '"Bu o kadar korkunç bir suç mu Basil? Sanki gençliğim sana bir hakaretmiş gibi konuşuyorsun!"', 'notes': 'insult to you: sana hakaret.'}]}, {'page_no': 12, 'title': 'The Confrontation in the Library', 'tr_title': 'Kütüphanedeki Yüzleşme', 'vocab_focus': [('accusation', 'itham, suçlama'), ('shameful', 'utanç verici, ayıp'), ('dishonor', 'onursuzluk, leke'), ('defense', 'savunma'), ('denial', 'inkar, yalanlama'), ('pure', 'saf, temiz'), ('soul', 'ruh, can'), ('dreadful', 'korkunç, dehşetli')], 'sentences': [{'id': 221, 'text': '"Dorian, it is not your youth I question; it is the dreadful things people are saying against you in London,"', 'translation': '"Dorian, sorguladığım şey senin gençliğin değil; Londra\'da insanların senin aleyhinde söylediği korkunç şeyler,"', 'notes': 'dreadful things: korkunç şeyler.'}, {'id': 222, 'text': "Basil's voice trembled with painful emotion as he took a step closer toward his former muse.", 'translation': "Eski esin kaynağına doğru bir adım daha atarken Basil'in sesi acı dolu bir duyguyla titriyordu.", 'notes': 'trembled with emotion: duyguyla titredi.'}, {'id': 223, 'text': '"I have heard accusations so terrible, so shameful, that I felt compelled to come here tonight and demand the truth."', 'translation': '"O kadar korkunç, o kadar utanç verici suçlamalar duydum ki bu gece buraya gelip gerçeği talep etmek zorunda hissettim."', 'notes': 'felt compelled: mecbur/zorunda hissetti.'}, {'id': 224, 'text': '"They say that you corrupt everyone who becomes intimate with you, leaving only disgrace and ruin behind."', 'translation': '"Seninle samimi olan herkesi yoldan çıkardığını, geride yalnızca rezillik ve yıkım bıraktığını söylüyorlar."', 'notes': 'corrupt everyone: herkesi yoldan çıkarmak.'}, {'id': 225, 'text': '"Why did Lord Henry\'s sister lose her reputation? Why did young Lord Poole shoot himself in his chambers?"', 'translation': '"Lord Henry\'nin kız kardeşi neden itibarını kaybetti? Genç Lord Poole neden odasında kendini vurdu?"', 'notes': 'lose reputation: itibarını kaybetmek.'}, {'id': 226, 'text': '"Why is Adrian Singleton haunting the worst opium dens of the East End, a penniless and broken wreck?"', 'translation': '"Adrian Singleton neden meteliksiz ve bitmiş bir enkaz halinde Doğu Yakası\'nın en berbat afyon tekkelerini mesken tutuyor?"', 'notes': 'broken wreck: bitmiş enkaz.'}, {'id': 227, 'text': '"Why does young Sir Henry Ashton leave the country in shame, refusing ever to hear your name uttered again?"', 'translation': '"Genç Sör Henry Ashton adının bir daha anılmasını bile reddederek neden utanç içinde ülkeyi terk etti?"', 'notes': 'in shame: utanç içinde.'}, {'id': 228, 'text': 'Dorian lounged back in his chair with an indifferent shrug, blowing a thin plume of grey smoke toward the ceiling.', 'translation': 'Dorian kayıtsızca omuz silkerek koltuğuna yaslandı, tavana doğru ince bir gri duman halkası üfledi.', 'notes': 'indifferent shrug: kayıtsız omuz silkiş.'}, {'id': 229, 'text': '"I am not responsible for the foolishness or vices of other men, Basil," Dorian replied disdainfully.', 'translation': '"Ben başka insanların ahmaklıklarından veya kusurlarından sorumlu değilim Basil," diye küçümseyerek yanıtladı Dorian.', 'notes': 'replied disdainfully: küçümseyerek yanıtladı.'}, {'id': 230, 'text': '"If people choose to ruin themselves through weak wills and bad habits, they have only themselves to blame."', 'translation': '"Eğer insanlar zayıf iradeleri ve kötü alışkanlıkları yüzünden kendilerini mahvetmeyi seçiyorlarsa yalnızca kendilerini suçlamalılar."', 'notes': 'only themselves to blame: sadece kendilerini suçlamalı.'}, {'id': 231, 'text': '"No, Dorian! You cannot brush these charges aside so lightly," Basil insisted with rising passion.', 'translation': '"Hayır Dorian! Bu suçlamaları bu kadar hafifçe bir kenara itemezsin," diye ısrar etti Basil yükselen bir tutkuyla.', 'notes': 'rising passion: yükselen tutku/coşku.'}, {'id': 232, 'text': '"Sin is a thing that writes itself across a man\'s face; it cannot be hidden from the eyes of the world."', 'translation': '"Günah, insanın yüzüne kendi kendini yazan bir şeydir; dünyanın gözlerinden gizlenemez."', 'notes': 'writes itself: kendini yazar.'}, {'id': 233, 'text': '"If a man lives a vile and dishonorable life, the lines of his mouth and the heavy shadows under his eyes betray him."', 'translation': '"Eğer bir adam alçak ve onursuz bir hayat yaşarsa, ağzının çizgileri ve gözlerinin altındaki ağır gölgeler onu ele verir."', 'notes': 'betray him: onu ele verir.'}, {'id': 234, 'text': '"Yet when I gaze upon you, I see the same pure, uncorrupted youth that inspired my greatest masterpiece."', 'translation': '"Oysa sana baktığımda, en büyük şaheserime ilham veren o aynı saf, bozulmamış gençliği görüyorum."', 'notes': 'uncorrupted youth: bozulmamış gençlik.'}, {'id': 235, 'text': '"And so I tell people that the rumors must be slander, that you are as innocent as an angel."', 'translation': '"Ve bu yüzden insanlara söylentilerin iftira olması gerektiğini, senin bir melek kadar masum olduğunu söylüyorum."', 'notes': 'rumors must be slander: dedikodular iftira olmalı.'}, {'id': 236, 'text': '"Yet I want to be certain! I want to look into your very soul to know whether you are good or evil!"', 'translation': '"Yine de emin olmak istiyorum! İyi mi yoksa kötü mü olduğunu bilmek için bizzat ruhunun ta içine bakmak istiyorum!"', 'notes': 'very soul: ruhun ta içi.'}, {'id': 237, 'text': '"Alas, only God can see the human soul, and man can only guess at what lies hidden within."', 'translation': '"Ne yazık ki yalnızca Tanrı insan ruhunu görebilir; insan ise içeride neyin saklı yattığını yalnızca tahmin edebilir."', 'notes': 'guess at what lies hidden: saklı yatanı tahmin etmek.'}, {'id': 238, 'text': "A bitter, mocking smile twisted Dorian's lips; a sudden, reckless impulse seized his feverish mind.", 'translation': "Acı, alaycı bir gülümseme Dorian'ın dudaklarını büktü; ani ve pervasız bir dürtü hummalı zihnini esir aldı.", 'notes': 'reckless impulse: pervasız dürtü.'}, {'id': 239, 'text': '"You believe that only God can see a man\'s soul, Basil?" Dorian asked in a low, dangerous whisper.', 'translation': '"Yalnızca Tanrı\'nın bir adamın ruhunu görebileceğine mi inanıyorsun Basil?" diye sordu Dorian alçak, tehlikeli bir fısıltıyla.', 'notes': 'dangerous whisper: tehlikeli fısıltı.'}, {'id': 240, 'text': '"Come upstairs with me, then, and I will show you what no living man has ever been permitted to see!"', 'translation': '"Benimle yukarı gel öyleyse, yaşayan hiçbir insanın görmesine izin verilmemiş olanı sana göstereyim!"', 'notes': 'permitted to see: görmesine izin verilmiş.'}]}, {'page_no': 13, 'title': 'Unveiling the Soul in the Locked Schoolroom', 'tr_title': 'Kilitli Okul Odasında Ruhun Açığa Çıkışı', 'vocab_focus': [('attic', 'çatı katı'), ('rusty key', 'paslı anahtar'), ('curtain', 'perde, örtü'), ('canvas', 'tuval'), ('grotesque', 'garip, ucube, acayip'), ('rotting', 'çürüyen'), ('shudder', 'ürpermek, titremek'), ('loathsome', 'iğrenç, tiksindirici')], 'sentences': [{'id': 241, 'text': 'Basil stared at him in utter bewilderment: "Come upstairs? What do you mean, Dorian?"', 'translation': 'Basil büyük bir şaşkınlıkla ona dik dik baktı: "Yukarı mı geleyim? Ne demek istiyorsun Dorian?"', 'notes': 'utter bewilderment: büyük/tam şaşkınlık.'}, {'id': 242, 'text': '"I mean that I shall keep my promise and show you my soul!" Dorian exclaimed with wild laughter.', 'translation': '"Sözümü tutup sana ruhumu göstereceğimi kastediyorum!" diye çılgınca bir kahkahayla haykırdı Dorian.', 'notes': 'keep my promise: sözümü tutmak.'}, {'id': 243, 'text': '"You created it, Basil; you worshiped it; it is only fitting that you should behold what it has become!"', 'translation': '"Onu sen yarattın Basil; ona sen taptın; neye dönüştüğünü görmen son derece yerindedir!"', 'notes': 'only fitting: son derece uygun/yerinde.'}, {'id': 244, 'text': 'He took a small brass lamp from the library table and gestured for the painter to follow him.', 'translation': 'Kütüphane masasından küçük bir pirinç lamba aldı ve ressama kendisini takip etmesi için işaret etti.', 'notes': 'gestured to follow: takip etmesi için işaret etti.'}, {'id': 245, 'text': 'They climbed the shadowy staircase in absolute silence, their footsteps echoing through the cold, empty house.', 'translation': 'Mutlak bir sessizlik içinde gölgeli merdivenleri tırmandılar; ayak sesleri soğuk, boş evde yankılanıyordu.', 'notes': 'shadowy staircase: gölgeli merdiven.'}, {'id': 246, 'text': 'At the very top landing, Dorian paused before the iron-studded oak door of the old schoolroom.', 'translation': 'En üst kattaki sahanlıkta Dorian, eski okul odasının demir çivili meşe kapısının önünde durakladı.', 'notes': 'iron-studded door: demir çivili kapı.'}, {'id': 247, 'text': 'He drew the secret key from beneath his shirt, fitted it into the intricate lock, and turned it firmly.', 'translation': 'Gömleğinin altından gizli anahtarı çıkardı, karmaşık kilide oturttu ve kararlılıkla çevirdi.', 'notes': 'intricate lock: karmaşık kilit.'}, {'id': 248, 'text': 'The heavy hinges groaned with a rusty shriek as the door swung open into the cold, neglected room.', 'translation': 'Kapı soğuk, bakımsız odaya doğru açılırken ağır menteşeler paslı bir çığlıkla inledi.', 'notes': 'hinges groaned: menteşeler inledi.'}, {'id': 249, 'text': 'A chill, damp smell of dust and stagnant air rushed out to meet them in the darkness.', 'translation': 'Karanlığın içinde onları karşılamak üzere dondurucu, nemli bir toz ve durgun hava kokusu dışarı hücum etti.', 'notes': 'stagnant air: durgun/havasız hava.'}, {'id': 250, 'text': 'Dorian placed the lamp upon a rickety table beside an easel covered by a purple and gold silk drape.', 'translation': 'Dorian lambayı mor ve altın rengi ipek bir örtüyle örtülmüş şövalenin yanındaki sallantılı masanın üzerine koydu.', 'notes': 'rickety table: sallantılı/çürük masa.'}, {'id': 251, 'text': '"So you think that only God can see a man\'s soul? Draw that curtain, Basil, and see mine!"', 'translation': '"Demek yalnızca Tanrı\'nın bir insanın ruhunu görebileceğini sanıyorsun? Çek şu perdeyi Basil ve benimkini gör!"', 'notes': 'draw that curtain: şu perdeyi çek.'}, {'id': 252, 'text': 'Basil shrank back with instinctive dread: "This is madness, Dorian! Why did you bring me up here?"', 'translation': 'Basil içgüdüsel bir dehşetle geriye sindi: "Bu delilik Dorian! Beni buraya neden çıkardın?"', 'notes': 'instinctive dread: içgüdüsel dehşet.'}, {'id': 253, 'text': '"If you will not pull it aside yourself, then I shall do it for you!" Dorian declared fiercely.', 'translation': '"Eğer örtüyü kendin yana çekmeyeceksen, o halde senin yerine ben yapacağım!" diye hiddetle bildirdi Dorian.', 'notes': 'pull aside: yana çekmek.'}, {'id': 254, 'text': 'With a swift, violent motion, Dorian tore the purple velvet drape away from the face of the canvas.', 'translation': 'Hızlı ve şiddetli bir hareketle Dorian mor kadife örtüyü tuvalin yüzünden çekip kopardı.', 'notes': 'violent motion: şiddetli hareket.'}, {'id': 255, 'text': "A cry of unutterable terror and revulsion burst from Basil Hallward's parted lips.", 'translation': "Tarif edilemez bir dehşet ve tiksinti çığlığı Basil Hallward'ın aralanan dudaklarından fırladı.", 'notes': 'unutterable terror: tarif edilemez dehşet.'}, {'id': 256, 'text': 'In the dim yellow lamplight grinned a loathsome, bloated face withered by unimaginable wickedness.', 'translation': 'Loş sarı lamba ışığında hayal bile edilemeyecek bir kötülükle buruşmuş, iğrenç, şişkin bir yüz sırıtıyordu.', 'notes': 'bloated face: şişkin/şişmiş yüz.'}, {'id': 257, 'text': 'The painted eyes were red and cunning, the cheeks sagging and yellowed like rotting parchment.', 'translation': 'Resmedilmiş gözler kırmızı ve sinsiydi; yanaklar çürüyen parşömen gibi sarkmış ve sararmıştı.', 'notes': 'rotting parchment: çürüyen parşömen.'}, {'id': 258, 'text': 'The cruel, sensual mouth dripped with an expression of bestial, depraved malice.', 'translation': 'Zalim, şehvet düşkünü ağız hayvanca ve yozlaşmış bir kötü niyet ifadesiyle dolup taşıyordu.', 'notes': 'depraved malice: yozlaşmış kötü niyet.'}, {'id': 259, 'text': "Yet through all the horrifying decay, Basil could still recognize the unmistakable outline of Dorian's features.", 'translation': "Fakat bütün o korkunç çürümenin içinden Basil, Dorian'ın yüz hatlarının su götürmez hatlarını hâlâ tanıyabiliyordu.", 'notes': 'unmistakable outline: su götürmez/belirgin hat.'}, {'id': 260, 'text': 'And there, in the bottom corner of the canvas, stood his own signature painted in long vermilion letters!', 'translation': 'Ve işte orada, tuvalin alt köşesinde, uzun vermilyon rengi harflerle resmedilmiş kendi imzası duruyordu!', 'notes': 'own signature: kendi imzası.'}]}, {'page_no': 14, 'title': "Basil's Despair and the Call to Repentance", 'tr_title': "Basil'in Umutsuzluğu ve Tövbe Çağrısı", 'vocab_focus': [('repentance', 'tövbe, pişmanlık'), ('damnation', 'lanetlenme, ebedi azap'), ('weep', 'ağlamak, gözyaşı dökmek'), ('prayer', 'dua'), ('forgiveness', 'bağışlanma, af'), ('conscience', 'vicdan'), ('monstrous', 'canavarca, korkunç'), ('mercy', 'merhamet, acıma')], 'sentences': [{'id': 261, 'text': '"Great God in heaven! What is this monstrosity?" Basil stammered, covering his eyes with trembling hands.', 'translation': '"Göklerdeki Yüce Tanrım! Nedir bu canavarlık?" diye kekeledi Basil, titreyen elleriyle gözlerini örterek.', 'notes': 'trembling hands: titreyen eller.'}, {'id': 262, 'text': '"This is the portrait you painted of me, Basil; this is the true face of my soul!" Dorian whispered coldly.', 'translation': '"Bu benim için yaptığın portre Basil; bu ruhumun gerçek yüzü!" diye soğukça fısıldadı Dorian.', 'notes': 'true face: gerçek yüz.'}, {'id': 263, 'text': '"It cannot be! The pigments I used never could have decayed into such foul, rotten discoloration!"', 'translation': '"Olamaz! Kullandığım boyalar asla bu kadar iğrenç, çürümüş bir renk bozulmasına uğramış olamaz!"', 'notes': 'rotten discoloration: çürümüş renk bozulması.'}, {'id': 264, 'text': '"It is not the paint that has decayed, my dear painter; it is the spiritual reality behind it."', 'translation': '"Çürüyen şey boya değil sevgili ressamım; ardındaki ruhani gerçeklik."', 'notes': 'spiritual reality: ruhani gerçeklik.'}, {'id': 265, 'text': '"Do you remember the day you finished this portrait, and Lord Henry spoke to me of the tragedy of aging?"', 'translation': '"Bu portreyi bitirdiğin ve Lord Henry\'nin bana yaşlanmanın trajedisinden söz ettiği o günü hatırlıyor musun?"', 'notes': 'tragedy of aging: yaşlanmanın trajedisi.'}, {'id': 266, 'text': '"I made a wish that sunny afternoon; I prayed that I might remain young forever and the portrait bear the burden."', 'translation': '"O güneşli öğleden sonra bir dilek tuttum; sonsuza dek genç kalayım da yükü portre taşısın diye dua ettim."', 'notes': 'bear the burden: yükü taşımak.'}, {'id': 267, 'text': '"And the prayer was answered! The picture has grown foul and decrepit, while I have walked untouched through time."', 'translation': '"Ve o dua kabul oldu! Resim kirlenip köhnedi, bense zamanın içinden hiç dokunulmadan geçip gittim."', 'notes': 'prayer was answered: dua kabul oldu.'}, {'id': 268, 'text': 'Basil sank down onto a dusty wooden chair, burying his face in his hands as tears slipped through his fingers.', 'translation': 'Gözyaşları parmaklarının arasından süzülürken Basil tozlu tahta bir sandalyeye çöktü ve yüzünü ellerine gömdü.', 'notes': 'sank down: yere/sandalyeye çöktü.'}, {'id': 269, 'text': '"If this is true, Dorian," Basil groaned, "then you are far more wicked and damned than the worst rumors ever claimed!"', 'translation': '"Eğer bu doğruysa Dorian," diye inledi Basil, "o halde en kötü söylentilerin iddia ettiğinden çok daha alçak ve lanetlisin!"', 'notes': 'far more wicked: çok daha alçak/kötü.'}, {'id': 270, 'text': '"You have destroyed your own soul for the sake of petty, fleeting pleasures!"', 'translation': '"Küçücük, gelip geçici zevkler uğruna kendi ruhunu mahvettin!"', 'notes': 'fleeting pleasures: gelip geçici zevkler.'}, {'id': 271, 'text': 'Basil looked up at the ghastly canvas again, his heart breaking for the boy he had once loved with all his soul.', 'translation': 'Basil bir zamanlar tüm ruhuyla sevdiği çocuk için yüreği parçalanarak o korkunç tuvale tekrar baktı.', 'notes': 'heart breaking: yüreği parçalanan.'}, {'id': 272, 'text': '"Dorian, it is not too late!" Basil suddenly cried, rising and seizing Dorian\'s cold hands in his own.', 'translation': '"Dorian, henüz çok geç değil!" diye ansızın haykırdı Basil; ayağa fırlayıp Dorian\'ın soğuk ellerini ellerinin arasına aldı.', 'notes': 'not too late: çok geç değil.'}, {'id': 273, 'text': '"The scripture says: \'Though your sins be as scarlet, they shall be made white as snow!\'"', 'translation': '"Kutsal kitap şöyle der: \'Günahlarınız al kırmızı olsa da kar gibi bembeyaz olacaklar!\'"', 'notes': 'white as snow: kar gibi beyaz.'}, {'id': 274, 'text': '"Let us kneel down together upon the bare floor and pray to God for mercy and redemption!"', 'translation': '"Çıplak zemine birlikte diz çökelim ve merhamet ve kurtuluş için Tanrı\'ya dua edelim!"', 'notes': 'kneel down together: birlikte diz çökmek.'}, {'id': 275, 'text': '"Pray with me, Dorian: \'Lead us not into temptation, but deliver us from evil!\'"', 'translation': '"Benimle birlikte dua et Dorian: \'Bizi ayartılmaya sürükleme, kötülükten kurtar!\'"', 'notes': 'deliver from evil: kötülükten kurtarmak.'}, {'id': 276, 'text': '"It is too late, Basil!" Dorian muttered hollowly; "My prayer was answered long ago; repentance is impossible."', 'translation': '"Çok geç Basil!" diye donukça mırıldandı Dorian; "Benim duam çoktan kabul oldu; tövbe etmek imkansız."', 'notes': 'repentance is impossible: tövbe etmek imkansız.'}, {'id': 277, 'text': '"It is never too late, Dorian! We both worshiped this image too much; let us destroy it and cleanse our hearts!"', 'translation': '"Asla çok geç değil Dorian! İkimiz de bu surete çok fazla taptık; onu yok edelim ve kalplerimizi arındıralım!"', 'notes': 'cleanse our hearts: kalplerimizi arındırmak.'}, {'id': 278, 'text': 'As Basil turned to look again at the portrait with eyes full of pious grief, an uncontrollable rage seized Dorian.', 'translation': "Basil gözleri dindarane bir kederle dolu halde tekrar portreye bakmak için döndüğünde Dorian'ı zapt edilemez bir öfke ele geçirdi.", 'notes': 'uncontrollable rage: zapt edilemez öfke.'}, {'id': 279, 'text': 'A monstrous hatred for the painter flared up within him like an erupting volcano.', 'translation': 'Ressama karşı canavarca bir nefret, patlayan bir yanardağ gibi içinde alevlendi.', 'notes': 'monstrous hatred: canavarca nefret.'}, {'id': 280, 'text': 'He felt that Basil was the true architect of his doom, the witness who held the secret of his damnation.', 'translation': "Basil'in felaketinin asıl mimarı, lanetlenmesinin sırrını elinde tutan tanık olduğunu hissetti.", 'notes': 'architect of doom: felaketin mimarı.'}]}, {'page_no': 15, 'title': 'The Murder of Basil Hallward', 'tr_title': "Basil Hallward'ın Öldürülmesi", 'vocab_focus': [('fury', 'öfke, hiddet'), ('weapon', 'silah'), ('strike', 'vurmak, darbe indirmek'), ('artery', 'atardamar'), ('agony', 'can çekişme, ıstırap'), ('motionless', 'hareketsiz'), ('lifeless', 'cansız'), ('accomplice', 'suç ortağı')], 'sentences': [{'id': 281, 'text': 'Dorian glanced wildly around the dimly lit room, his heart pounding like a muffled drum.', 'translation': 'Dorian loş ışıklı odaya delicesine bakındı; kalbi boğuk bir davul gibi çarpıyordu.', 'notes': 'pounding like a drum: davul gibi çarpan.'}, {'id': 282, 'text': 'Upon the painted wooden chest beside the wall lay a heavy hunting knife he had left there months before.', 'translation': 'Duvarın yanındaki boyalı tahta sandığın üzerinde aylar önce oraya bıraktığı ağır bir av bıçağı duruyordu.', 'notes': 'hunting knife: av bıçağı.'}, {'id': 283, 'text': 'He moved toward the weapon with the silent, creeping stealth of a stalking panther.', 'translation': 'Avına yaklaşan bir panterin sessiz, sinsi adımlarıyla silaha doğru ilerledi.', 'notes': 'creeping stealth: sinsi adımlar.'}, {'id': 284, 'text': 'Basil was still sitting with bowed head before the easel, murmuring a quiet, desperate prayer.', 'translation': 'Basil hâlâ şövalenin önünde başı öne eğik oturuyor, sessiz, çaresiz bir dua mırıldanıyordu.', 'notes': 'bowed head: öne eğik baş.'}, {'id': 285, 'text': "Dorian grasped the knife's horn handle, his knuckles whitening with ferocious, mad determination.", 'translation': 'Dorian bıçağın boynuz kabzasını kavradı; parmak boğumları vahşi, delice bir kararlılıkla beyazlaştı.', 'notes': 'ferocious determination: vahşi kararlılık.'}, {'id': 286, 'text': "He rushed behind Basil's chair, raised the heavy blade high, and drove it violently into the painter's neck!", 'translation': "Basil'in sandalyesinin arkasına atıldı, ağır namluyu havaya kaldırdı ve şiddetle ressamın boynuna sapladı!", 'notes': 'drove the blade: namluyu sapladı.'}, {'id': 287, 'text': "A terrible, gurgling gasp escaped Basil's throat as the steel severed the vital carotid artery.", 'translation': "Çelik namlu hayati atardamarı keserken Basil'in boğazından korkunç, hırıltılı bir soluk koptu.", 'notes': 'gurgling gasp: hırıltılı soluk/nefes.'}, {'id': 288, 'text': 'Basil struggled violently to rise, his arms flailing desperately in the empty air.', 'translation': 'Kolları boşlukta çaresizce savrularak Basil ayağa kalkmak için şiddetle çırpındı.', 'notes': 'struggled violently: şiddetle çırpındı.'}, {'id': 289, 'text': "Dorian struck again and again, plunging the bloody blade three more times into the writhing man's throat.", 'translation': 'Dorian kanlı namluyu kıvranan adamın boğazına üç kez daha saplayarak defalarca vurdu.', 'notes': 'writhing man: kıvranan adam.'}, {'id': 290, 'text': 'There was a heavy groan, the dull thud of an overturned chair, and then horrifying, suffocating silence.', 'translation': 'Ağır bir inilti, devrilen bir sandalyenin tok gürültüsü ve ardından dehşet verici, boğucu bir sessizlik oldu.', 'notes': 'suffocating silence: boğucu sessizlik.'}, {'id': 291, 'text': 'Basil Hallward lay motionless upon the floor, a dark, steaming pool of crimson spreading beneath his head.', 'translation': 'Basil Hallward yerde hareketsiz yatıyordu; başının altından koyu, buharı tüten kızıl bir kan gölü yayılıyordu.', 'notes': 'crimson pool: kızıl kan gölü.'}, {'id': 292, 'text': 'Dorian stood over the body, breathing heavily, watching the life drain forever from his oldest friend.', 'translation': 'Dorian en eski dostundan yaşamın ebediyen çekilip gidişini izleyerek ağır ağır soluk alıp cesedin başında dikildi.', 'notes': 'life drain forever: yaşamın sonsuza dek çekilmesi.'}, {'id': 293, 'text': 'Strangely, he felt no remorse, no terror, only an astonishing, icy detachment.', 'translation': 'Tuhaf bir şekilde hiçbir pişmanlık, hiçbir dehşet hissetmedi; yalnızca şaşırtıcı, buz gibi bir hissizlik duydu.', 'notes': 'icy detachment: buz gibi hissizlik/kayıtsızlık.'}, {'id': 294, 'text': 'He carefully wiped the bloodstained knife upon a corner of an old curtain and set it down.', 'translation': 'Kanlı bıçağı eski bir perdenin köşesine dikkatlice sildi ve yere bıraktı.', 'notes': 'bloodstained knife: kanlı bıçak.'}, {'id': 295, 'text': 'He covered the ruined portrait once more with the purple silk drape, hiding the gruesome observer.', 'translation': 'Korkunç gözlemciyi saklayarak mahvolmuş portreyi mor ipek örtüyle bir kez daha örttü.', 'notes': 'gruesome observer: korkunç gözlemci.'}, {'id': 296, 'text': 'Then he picked up the brass lamp, blew it out, stepped quietly from the chamber, and locked the door behind him.', 'translation': 'Ardından pirinç lambayı aldı, üfleyip söndürdü, odadan sessizce çıktı ve kapıyı arkasından kilitledi.', 'notes': 'stepped quietly: sessizce çıktı.'}, {'id': 297, 'text': "He slipped down to the hallway, retrieved Basil's heavy ulster and hat, and hid them inside a secret cabinet.", 'translation': "Salona indi, Basil'in kalın paltosunu ve şapkasını aldı ve onları gizli bir dolaba sakladı.", 'notes': 'secret cabinet: gizli dolap.'}, {'id': 298, 'text': 'To establish an alibi, he stepped outside the front door into the fog and pulled the brass bell firmly.', 'translation': 'Bir mazeret oluşturmak için ön kapıdan sisin içine çıktı ve pirinç zili kararlılıkla çaldı.', 'notes': 'establish an alibi: mazeret/alibi oluşturmak.'}, {'id': 299, 'text': 'When the drowsy servant Francis opened the door, Dorian asked politely what time it was.', 'translation': 'Uykulu hizmetkar Francis kapıyı açtığında Dorian nazikçe saatin kaç olduğunu sordu.', 'notes': 'drowsy servant: uykulu hizmetkar.'}, {'id': 300, 'text': '"Ten minutes past two, sir," the servant replied, convinced his master had just returned from an evening out.', 'translation': '"İkiyi on geçiyor efendim," diye yanıtladı hizmetkar; efendisinin gece gezmesinden yeni döndüğüne tamamen inanarak.', 'notes': 'evening out: gece gezmesi.'}]}, {'page_no': 16, 'title': 'The Morning After and the Summons to Alan Campbell', 'tr_title': "Ertesi Sabah ve Alan Campbell'a Çağrı", 'vocab_focus': [('breakfast', 'kahvaltı'), ('composure', 'soğukkanlılık, sükunet'), ('chemist', 'kimyager'), ('estrangement', 'yabancılaşma, küslük'), ('courier', 'kurye, ulak'), ('summons', 'çağrı, davet'), ('reluctant', 'gönülsüz, isteksiz'), ('dread', 'dehşet, büyük korku')], 'sentences': [{'id': 301, 'text': "The next morning at nine o'clock, Dorian awoke from a deep, untroubled slumber, feeling entirely refreshed.", 'translation': 'Ertesi sabah saat dokuzda Dorian, kendini tamamen dinlenmiş hissederek derin ve tasasız bir uykudan uyandı.', 'notes': 'untroubled slumber: tasasız/rahat uyku.'}, {'id': 302, 'text': 'The morning sun shone palely through the curtains, illuminating the luxurious appointments of his bedroom.', 'translation': 'Sabah güneşi perdelerin arasından solukça parlıyor, yatak odasının lüks döşemelerini aydınlatıyordu.', 'notes': 'luxurious appointments: lüks döşemeler.'}, {'id': 303, 'text': 'For a few peaceful minutes, he lay upon his pillows, enjoying the quiet comfort of his surroundings.', 'translation': 'Birkaç huzurlu dakika boyunca yastıklarının üzerine uzanıp çevresinin sessiz konforunun tadını çıkardı.', 'notes': 'quiet comfort: sessiz konfor.'}, {'id': 304, 'text': 'Then, like a sudden flash of lightning, the horrifying memory of the midnight murder rushed into his mind.', 'translation': 'Ardından, ani bir şimşek çakması gibi, gece yarısı cinayetinin korkunç anısı zihnine hücum etti.', 'notes': 'flash of lightning: şimşek çakması.'}, {'id': 305, 'text': 'He remembered the dead man sitting upstairs in the locked schoolroom, bathed in his own coagulated blood.', 'translation': 'Yukarıda kilitli okul odasında, kendi pıhtılaşmış kanı içinde oturan o ölü adamı hatırladı.', 'notes': 'coagulated blood: pıhtılaşmış kan.'}, {'id': 306, 'text': 'Yet his pulse did not quicken; a strange, unnatural composure seemed to envelop his whole being.', 'translation': 'Fakat nabzı hızlanmadı; tuhaf, doğal olmayan bir soğukkanlılık bütün benliğini kuşatır gibiydi.', 'notes': 'unnatural composure: doğal olmayan soğukkanlılık.'}, {'id': 307, 'text': 'He rang the bell for his valet, bathed with exquisite care, and dressed in an elegant morning suit.', 'translation': 'Uşağı için zili çaldı, büyük bir özenle banyo yaptı ve şık bir sabah takım elbisesi giydi.', 'notes': 'exquisite care: büyük özen.'}, {'id': 308, 'text': 'He sat down in his dining room and ate a light breakfast of French omelet, toast, and fragrant coffee.', 'translation': 'Yemek odasına oturdu ve Fransız omleti, kızarmış ekmek ve mis kokulu kahveden oluşan hafif bir kahvaltı yaptı.', 'notes': 'fragrant coffee: mis kokulu kahve.'}, {'id': 309, 'text': 'He read through his morning letters and skimmed the social columns of the newspaper with complete calm.', 'translation': 'Sabah mektuplarını baştan sona okudu ve tam bir sükunetle gazetenin cemiyet sütunlarına göz gezdirdi.', 'notes': 'complete calm: tam bir sükunet.'}, {'id': 310, 'text': "He knew that Basil's disappearance would not cause alarm for months, since Basil was believed to be in Paris.", 'translation': "Basil'in Paris'te olduğuna inanıldığı için ortadan kayboluşunun aylarca telaşa yol açmayacağını biliyordu.", 'notes': 'cause alarm: telaşa/paniğe yol açmak.'}, {'id': 311, 'text': 'The cab driver who had driven Basil to the house would never remember picking up an ordinary traveler in the fog.', 'translation': "Basil'i eve getiren fayton şoförü sisin içinde sıradan bir yolcuyu aldığını asla hatırlamayacaktı.", 'notes': 'ordinary traveler: sıradan yolcu.'}, {'id': 312, 'text': 'However, the decaying corpse remained upstairs, an intolerable danger that had to be eliminated without delay.', 'translation': 'Yine de çürüyen ceset yukarıda duruyordu; gecikmeksizin ortadan kaldırılması gereken tahammül edilemez bir tehlikeydi.', 'notes': 'intolerable danger: tahammül edilemez tehlike.'}, {'id': 313, 'text': 'Dorian considered his options: burying the body or hauling it outside was utterly out of the question.', 'translation': 'Dorian seçeneklerini değerlendirdi: Cesedi gömmek ya da dışarı taşımak kesinlikle söz konusu bile olamazdı.', 'notes': 'out of the question: söz konusu bile olamaz.'}, {'id': 314, 'text': 'Only one man in London possessed the specialized scientific knowledge required to destroy organic matter entirely.', 'translation': "Londra'da organik maddeyi tamamen yok etmek için gereken uzmanlaşmış bilimsel bilgiye yalnızca tek bir adam sahipti.", 'notes': 'scientific knowledge: bilimsel bilgi.'}, {'id': 315, 'text': 'That man was Alan Campbell, a brilliant young chemist with whom Dorian had once been intensely intimate.', 'translation': "O adam, Dorian'ın bir zamanlar son derece yakın dost olduğu parlak bir genç kimyager olan Alan Campbell idi.", 'notes': 'intensely intimate: son derece yakın/samimi.'}, {'id': 316, 'text': 'Their friendship had ended abruptly years before, and Campbell now avoided Dorian with open revulsion.', 'translation': "Dostlukları yıllar önce aniden sona ermişti ve Campbell artık açık bir tiksintiyle Dorian'dan uzak duruyordu.", 'notes': 'open revulsion: açık tiksinti.'}, {'id': 317, 'text': "Dorian sat at his desk and penned a brief, commanding note requesting Campbell's immediate presence on a matter of life and death.", 'translation': "Dorian masasına oturdu ve bir ölüm kalım meselesi üzerine Campbell'ın derhal gelmesini talep eden kısa, emredici bir pusula yazdı.", 'notes': 'life and death: ölüm kalım.'}, {'id': 318, 'text': "He summoned a trusted footman and instructed him to deliver the letter directly into Mr. Campbell's hands.", 'translation': "Güvendiği bir uşağı çağırdı ve mektubu doğrudan Bay Campbell'ın eline teslim etmesini emretti.", 'notes': 'directly into hands: doğrudan ellerine.'}, {'id': 319, 'text': '"Wait for an answer, Francis, and bring Mr. Campbell back in a hansom cab if you possibly can,"', 'translation': '"Bir yanıt bekle Francis ve mümkünse Bay Campbell\'ı bir faytonla buraya geri getir,"', 'notes': 'wait for an answer: bir yanıt bekle.'}, {'id': 320, 'text': 'Dorian then settled back into his armchair, waiting with icy patience for his former friend to arrive.', 'translation': 'Dorian ardından koltuğuna geri yerleşti; eski dostunun gelişini buz gibi bir sabırla beklemeye başladı.', 'notes': 'icy patience: buz gibi sabır.'}]}, {'page_no': 17, 'title': 'The Blackmail and the Chemical Annihilation', 'tr_title': 'Şantaj ve Kimyasal Yok Ediş', 'vocab_focus': [('blackmail', 'şantaj yapmak, şantaj'), ('laboratory', 'laboratuvar'), ('apparatus', 'cihaz, deney aleti'), ('nitric acid', 'nitrik asit'), ('stench', 'pis koku, keskin koku'), ('annihilation', 'yok etme, imha'), ('destruction', 'yıkım, tahribat'), ('remorse', 'pişmanlık, vicdan azabı')], 'sentences': [{'id': 321, 'text': 'At half-past eleven, Alan Campbell entered the library, looking pale, stern, and coldly disdainful.', 'translation': 'Saat on bir buçukta Alan Campbell solgun, sert ve soğuk bir küçümsemeyle kütüphaneye girdi.', 'notes': 'coldly disdainful: soğuk bir küçümsemeyle.'}, {'id': 322, 'text': '"I swore never to enter your house again, Dorian," Campbell declared, refusing the offered chair.', 'translation': '"Evinize bir daha asla ayak basmamaya yemin etmiştim Dorian," diye bildirdi Campbell, teklif edilen sandalyeyi reddederek.', 'notes': 'refusing the chair: sandalyeyi reddederek.'}, {'id': 323, 'text': '"Only your urgent plea of life and death induced me to come here this morning."', 'translation': '"Bu sabah buraya gelmemi yalnızca ölüm kalım konusundaki acil yalvarışınız sağladı."', 'notes': 'urgent plea: acil yalvarış.'}, {'id': 324, 'text': '"Alan, there is a dead body in a locked room upstairs," Dorian said in a calm, flat tone.', 'translation': '"Alan, yukarıda kilitli bir odada ölü bir ceset var," dedi Dorian sakin ve düz bir ses tonuyla.', 'notes': 'flat tone: düz/duygusuz ton.'}, {'id': 325, 'text': '"The man was killed last night, and you must destroy the corpse so that not a single trace remains."', 'translation': '"Adam dün gece öldürüldü ve tek bir iz bile kalmayacak şekilde cesedi yok etmelisin."', 'notes': 'destroy the corpse: cesedi yok etmek.'}, {'id': 326, 'text': 'Campbell gasped in horror, recoiling toward the library door: "You murdered him! You want me to be an accomplice!"', 'translation': 'Campbell dehşet içinde soluğunu tuttu, kütüphane kapısına doğru geriledi: "Onu sen öldürdün! Suç ortağın olmamı istiyorsun!"', 'notes': 'gasped in horror: dehşetle soluğunu tuttu.'}, {'id': 327, 'text': '"I refuse utterly! I will have nothing to do with your monstrous crimes! Turn yourself in to the police!"', 'translation': '"Kesinlikle reddediyorum! Canavarca suçlarınla hiçbir ilgim olmayacak! Git polise teslim ol!"', 'notes': 'refuse utterly: kesinlikle reddetmek.'}, {'id': 328, 'text': 'Dorian smiled faintly, took a sheet of paper, wrote a few lines upon it, and handed it to the chemist.', 'translation': 'Dorian hafifçe gülümsedi, bir kağıt aldı, üzerine birkaç satır yazdı ve kimyagere uzattı.', 'notes': 'handed to chemist: kimyagere uzattı.'}, {'id': 329, 'text': 'As Alan Campbell read the words, every drop of blood drained from his face, leaving him shivering with dread.', 'translation': 'Alan Campbell kelimeleri okurken yüzündeki bütün kan çekildi ve onu dehşet içinde tir tir titrer halde bıraktı.', 'notes': 'shivering with dread: dehşetle titreyen.'}, {'id': 330, 'text': '"You would not dare to send this letter! It would ruin me forever!" Campbell cried in agonizing despair.', 'translation': '"Bu mektubu göndermeye cesaret edemezsin! Beni sonsuza dek mahveder!" diye acı dolu bir umutsuzlukla haykırdı Campbell.', 'notes': 'agonizing despair: acı dolu umutsuzluk.'}, {'id': 331, 'text': '"You know that I will send it without hesitation if you refuse to help me," Dorian replied pitilessly.', 'translation': '"Eğer bana yardım etmeyi reddedersen hiç tereddüt etmeden göndereceğimi biliyorsun," diye acımasızca yanıtladı Dorian.', 'notes': 'replied pitilessly: acımasızca yanıtladı.'}, {'id': 332, 'text': 'Trapped by his past secret, Campbell slumped into a chair and whispered brokenly: "I will do it."', 'translation': 'Geçmişindeki sırrın tuzağına düşen Campbell bir sandalyeye çöktü ve kırık bir sesle fısıldadı: "Yapacagım."', 'notes': 'whispered brokenly: kırık bir sesle fısıldadı.'}, {'id': 333, 'text': 'Campbell sent a servant to his laboratory to retrieve glass carboys of nitric acid, rubber tubes, and special burners.', 'translation': 'Campbell, cam damacanalar dolusu nitrik asidi, kauçuk boruları ve özel bekleri getirmesi için laboratuvarına bir hizmetkar yolladı.', 'notes': 'nitric acid: nitrik asit.'}, {'id': 334, 'text': 'When the apparatus arrived, Dorian led the trembling scientist up the dusty stairs to the attic.', 'translation': 'Cihazlar geldiğinde Dorian titreyen bilim insanını tozlu merdivenlerden çatı katına çıkardı.', 'notes': 'trembling scientist: titreyen bilim insanı.'}, {'id': 335, 'text': 'Campbell entered the locked schoolroom alone, locking the door firmly from the inside as he had demanded.', 'translation': 'Campbell talep ettiği üzere kapıyı içeriden sıkıca kilitleyerek kilitli okul odasına tek başına girdi.', 'notes': 'entered alone: tek başına girdi.'}, {'id': 336, 'text': 'For five agonizing hours, Dorian waited downstairs, hearing only muffled clinking of glass and the faint hiss of fire.', 'translation': 'Beş ıstırap dolu saat boyunca Dorian aşağıda bekledi; yalnızca camların boğuk şıngırtısını ve ateşin hafif tıslamasını duyuyordu.', 'notes': 'muffled clinking: boğuk şıngırtı.'}, {'id': 337, 'text': 'A sickening, pungent odor of burnt chemicals and acid seeped through the cracks of the floorboards.', 'translation': 'Döşeme tahtalarının çatlaklarından yanmış kimyasalların ve asidin mide bulandırıcı, keskin bir kokusu sızıyordu.', 'notes': 'pungent odor: keskin koku.'}, {'id': 338, 'text': "At four o'clock in the afternoon, Campbell came downstairs, his face pale as death and his hands shaking uncontrollably.", 'translation': 'Öğleden sonra saat dörtte Campbell aşağı indi; yüzü ölüm gibi solgundu ve elleri zaptedilemez bir biçimde titriyordu.', 'notes': 'pale as death: ölüm gibi solgun.'}, {'id': 339, 'text': '"I have done what you commanded," Campbell muttered without looking at Dorian; "the thing is gone forever."', 'translation': '"Emrettiğin şeyi yaptım," diye mırıldandı Campbell, Dorian\'ın yüzüne bakmaksızın; "o şey sonsuza dek yok oldu."', 'notes': 'thing is gone: o şey yok oldu.'}, {'id': 340, 'text': 'Dorian went upstairs to check: the chair was empty, the blood wiped clean, and only a terrible chemical odor lingered.', 'translation': 'Dorian kontrol etmek için yukarı çıktı: Sandalye boştu, kan tertemiz silinmişti ve geride yalnızca korkunç bir kimyasal koku kalmıştı.', 'notes': 'terrible chemical odor: korkunç kimyasal koku.'}]}, {'page_no': 18, 'title': 'Night Journey to the Riverfront Opium Dens', 'tr_title': 'Nehir Kıyısındaki Afyon Tekkelerine Gece Yolculuğu', 'vocab_focus': [('hansom cab', 'iki tekerlekli at arabası'), ('waterfront', 'nehir kıyısı, rıhtım'), ('fog', 'sis'), ('opium', 'afyon'), ('oblivion', 'unutuş, kayıtsızlık'), ('squalor', 'sefalet, pislik'), ('docks', 'rıhtımlar, tersaneler'), ('intoxicated', 'sarhoş olmuş, kendinden geçmiş')], 'sentences': [{'id': 341, 'text': "Although the physical evidence of the murder was destroyed, Dorian's mind found no tranquility or peace.", 'translation': "Cinayetin fiziksel kanıtları yok edilmiş olsa da Dorian'ın zihni ne bir huzur ne de bir dinginlik bulabildi.", 'notes': 'found no tranquility: huzur bulamadı.'}, {'id': 342, 'text': "Every quiet corner of his luxurious mansion seemed haunted by Basil Hallward's dying, gurgling gasp.", 'translation': "Lüks malikanesinin her sessiz köşesi Basil Hallward'ın can çekişirkenki hırıltılı nefesiyle lanetlenmiş gibiydi.", 'notes': 'gurgling gasp: hırıltılı son nefes.'}, {'id': 343, 'text': 'He craved absolute oblivion, the artificial paradise where memories could be bought and conscience put to sleep.', 'translation': 'Anıların satın alınabildiği ve vicdanın uyutulabildiği o yapay cenneti, mutlak bir unutuşu deli gibi arzuluyordu.', 'notes': 'craved oblivion: unutuşu arzuladı.'}, {'id': 344, 'text': 'Late that evening, he dressed himself in common, rough clothes and wrapped a coarse woolen muffler around his throat.', 'translation': 'O akşamın geç saatlerinde sıradan, kaba giysiler giydi ve boğazına kaba yünlü bir atkı doladı.', 'notes': 'woolen muffler: yün atkı.'}, {'id': 345, 'text': 'He stepped into the foggy night and hailed a passing hansom cab at the corner of the square.', 'translation': 'Sisli geceye adım attı ve meydanın köşesinde yoldan geçen iki tekerlekli bir faytona el etti.', 'notes': 'hailed a cab: faytona el etti/çağırdı.'}, {'id': 346, 'text': 'He promised the driver a sovereign if he drove at maximum speed toward the remote riverfront docks of East London.', 'translation': "Londra'nın Doğu Yakası'ndaki uzak rıhtımlara son sürat sürerse sürücüye bir altın sovereign bahşiş vadetti.", 'notes': 'maximum speed: azami hız.'}, {'id': 347, 'text': 'The horse dashed through the gloomy avenues, splashing dark mud against the carriage windows.', 'translation': 'At, fayton camlarına koyu çamurlar sıçratarak kasvetli caddeler boyunca dörtnala koştu.', 'notes': 'splashing dark mud: koyu çamurlar sıçratan.'}, {'id': 348, 'text': 'As they approached the Thames, the fog grew thicker, smelling foully of damp coal smoke and stagnant river slime.', 'translation': "Thames Nehri'ne yaklaştıkça sis daha da yoğunlaştı; nemli kömür dumanı ve durgun nehir balçığı gibi pis pis kokuyordu.", 'notes': 'stagnant river slime: durgun nehir balçığı.'}, {'id': 349, 'text': 'They entered a desolate district of narrow, labyrinthine alleys flanked by crumbling brick warehouses.', 'translation': 'Yıkılmaya yüz tutmuş tuğla depolarla çevrili dar, labirent gibi ara sokaklardan oluşan ıssız bir semte girdiler.', 'notes': 'desolate district: ıssız semt.'}, {'id': 350, 'text': 'Dorian paid the cabman, dismissed the carriage, and vanished on foot down a shadowy, sinister lane.', 'translation': 'Dorian faytoncunun parasını ödedi, arabayı savdı ve gölgeli, tekinsiz bir sokakta yaya olarak kayboldu.', 'notes': 'vanished on foot: yaya olarak kayboldu.'}, {'id': 351, 'text': 'He reached a decrepit wooden tavern standing beside a black, oily wharf where the tide was lapping.', 'translation': 'Gelgitin sularını vurduğu siyah, yağlı bir rıhtımın yanında duran köhne, ahşap bir meyhaneye ulaştı.', 'notes': 'decrepit tavern: köhne meyhane.'}, {'id': 352, 'text': 'He pushed open the creaking door and descended a flight of slippery stone steps into the cellar.', 'translation': 'Gıcırdayan kapıyı iterek açtı ve kaygan taş basamaklardan mahzene doğru aşağı indi.', 'notes': 'slippery stone steps: kaygan taş basamaklar.'}, {'id': 353, 'text': 'The room was hot, suffocating, and filled with the heavy, sickeningly sweet fumes of burning opium.', 'translation': 'Oda sıcaktı, boğucuydu ve yanan afyonun ağır, mide bulandırıcı derecede tatlı dumanlarıyla doluydu.', 'notes': 'suffocating fumes: boğucu dumanlar.'}, {'id': 354, 'text': 'Upon low wooden bunks along the walls lay ragged figures, breathing heavily in drug-induced stupor.', 'translation': 'Duvarlar boyunca uzanan alçak tahta kerevetlerde, uyuşturucunun getirdiği sersemlik içinde ağır nefesler alan yırtık pırtık kılıklı siluetler yatıyordu.', 'notes': 'drug-induced stupor: uyuşturucunun yol açtığı sersemlik.'}, {'id': 355, 'text': 'Foreign sailors, penniless thieves, and broken outcasts lay side by side, seeking escape from misery.', 'translation': 'Yabancı denizciler, meteliksiz hırsızlar ve hayatı mahvolmuş dışlanmışlar sefaletten kaçış arayarak yan yana yatıyorlardı.', 'notes': 'broken outcasts: hayatı mahvolmuş dışlanmışlar.'}, {'id': 356, 'text': 'A young man with sunken, feverish eyes sat slumped at a wooden table in the darkest corner.', 'translation': 'En karanlık köşedeki tahta bir masada çökmüş, hummalı gözleri olan genç bir adam yığılmış oturuyordu.', 'notes': 'sunken feverish eyes: çökmüş hummalı gözler.'}, {'id': 357, 'text': 'Dorian recognized Adrian Singleton, the promising gentleman whose life he had ruined years before.', 'translation': "Dorian yıllar önce hayatını mahvettiği o umut vadeden beyefendiyi, Adrian Singleton'ı tanıdı.", 'notes': 'promising gentleman: umut vadeden beyefendi.'}, {'id': 358, 'text': '"Adrian, is that you?" Dorian whispered, feeling a sudden prick of discomfort at the unexpected encounter.', 'translation': '"Adrian, sen misin?" diye fısıldadı Dorian, bu beklenmedik karşılaşma karşısında ani bir rahatsızlık duyarak.', 'notes': 'unexpected encounter: beklenmedik karşılaşma.'}, {'id': 359, 'text': '"Leave me alone, Dorian," Adrian muttered dully; "I have found my home here among the lost souls."', 'translation': '"Beni yalnız bırak Dorian," diye donukça mırıldandı Adrian; "Ben kayıp ruhlar arasında evimi burada buldum."', 'notes': 'lost souls: kayıp ruhlar.'}, {'id': 360, 'text': 'Disgusted and unsettled, Dorian turned on his heel, resolved to seek another opium den further down the docks.', 'translation': 'Tiksinti duyan ve huzuru kaçan Dorian, rıhtımın daha ilerisinde başka bir afyon tekkesi aramaya kararlı olarak arkasını döndü.', 'notes': 'turned on heel: arkasını döndü.'}]}, {'page_no': 19, 'title': 'The Encounter with Sailor Jim Vane', 'tr_title': 'Denizci Jim Vane ile Karşılaşma', 'vocab_focus': [('sailor', 'denizci'), ('vengeance', 'intikam, öç'), ('moniker', 'lakap, takma ad'), ('revolver', 'altıpatlar, tabanca'), ('choke', 'boğmak, soluğunu kesmek'), ('sister', 'kız kardeş'), ('eighteen', 'on sekiz'), ('confrontation', 'yüzleşme, çatışma')], 'sentences': [{'id': 361, 'text': 'As Dorian walked toward the tavern entrance, an old, ragged woman seated by the doorway peered up at him.', 'translation': 'Dorian meyhanenin girişine doğru yürürken kapı kenarında oturan eski püskü giyimli yaşlı bir kadın başını kaldırıp ona baktı.', 'notes': 'peered up: başını kaldırıp baktı.'}, {'id': 362, 'text': 'Dorian dropped a silver florin into her withered hand without stopping or glancing in her direction.', 'translation': 'Dorian durmaksızın veya o tarafa hiç bakmaksızın kadının buruşuk eline gümüş bir florin bıraktı.', 'notes': 'withered hand: buruşuk el.'}, {'id': 363, 'text': '"There goes the devil\'s bargain!" the woman cackled loudly into the smoky room.', 'translation': '"İşte şeytanın pazarlığı gidiyor!" diye duman altı odada tiz bir kahkahayla bağırdı kadın.', 'notes': 'cackled loudly: tiz kahkahayla bağırdı.'}, {'id': 364, 'text': '"Curse you, old hag! Do not speak to me!" Dorian snapped irritably, pushing past her into the dark alley.', 'translation': '"Lanet olsun sana koca karı! Benimle konuşma!" diye terslendi Dorian öfkeyle, kadını geçip karanlık ara sokağa çıkarak.', 'notes': 'snapped irritably: öfkeyle terslendi.'}, {'id': 365, 'text': '"You can curse me if you like, Prince Charming!" the woman shrieked after him with mocking spite.', 'translation': '"İstediğin kadar lanet oku bana Beyaz Atlı Prens!" diye arkasından alaycı bir kinle ciyakladı kadın.', 'notes': 'mocking spite: alaycı kin.'}, {'id': 366, 'text': 'At the utterance of that specific name, a burly sailor sleeping on a bench in the corner leaped to his feet.', 'translation': 'O özel lakabın telaffuz edilmesiyle köşedeki bir sırada uyuyan iri yarı bir denizci ayağa fırladı.', 'notes': 'leaped to feet: ayağa fırladı.'}, {'id': 367, 'text': 'His bronze, weathered face was twisted with sudden, savage fury as he rushed through the open door.', 'translation': 'Açık kapıdan dışarı fırlarken bronzlaşmış, yıpranmış yüzü ani ve vahşi bir öfkeyle bükülmüştü.', 'notes': 'savage fury: vahşi öfke.'}, {'id': 368, 'text': 'Dorian was walking rapidly through the damp mist when heavy boots thudded loudly behind him on the cobbles.', 'translation': 'Dorian nemli sisin içinde hızla yürürken arkasındaki arnavut kaldırımlarında ağır çizmeler gümbürdedi.', 'notes': 'walking rapidly: hızla yürüyen.'}, {'id': 369, 'text': 'Before he could turn, a pair of iron hands seized him violently by the throat and slammed him against a brick wall.', 'translation': 'Henüz dönemeden demir gibi iki el boğazından şiddetle yakaladı ve onu bir tuğla duvara çarptı.', 'notes': 'seized by throat: boğazından yakaladı.'}, {'id': 370, 'text': 'Dorian choked, gasping for breath, as he stared into the ferocious eyes of an armed, furious stranger.', 'translation': 'Silahlı ve öfkeli bir yabancının vahşi gözlerine bakarken Dorian nefes nefese kalarak boğulur gibi oldu.', 'notes': 'gasping for breath: nefes nefese kalan.'}, {'id': 371, 'text': '"What do you want? Let me go!" Dorian cried out, struggling against the man\'s crushing grip.', 'translation': '"Ne istiyorsun? Bırak beni!" diye haykırdı Dorian, adamın ezici pençesine karşı çırpınarak.', 'notes': 'crushing grip: ezici tutuş/kavrayış.'}, {'id': 372, 'text': '"Keep quiet, or I\'ll blow your brains out!" the sailor snarled, thrusting the cold barrel of a revolver against Dorian\'s temple.', 'translation': '"Sesini kes yoksa beynini dağıtırım!" diye hırladı denizci, bir altıpatların soğuk namlusunu Dorian\'ın şakağına dayayarak.', 'notes': 'cold barrel: soğuk namlu.'}, {'id': 373, 'text': '"I don\'t know you! Why are you attacking me?" Dorian pleaded, terrified by the sudden peril.', 'translation': '"Seni tanımıyorum! Bana neden saldırıyorsun?" diye yalvardı Dorian, bu ani tehlikeden dehşete düşerek.', 'notes': 'sudden peril: ani tehlike.'}, {'id': 374, 'text': '"You don\'t know me, but I know who you are!" the sailor rasped with deep, burning hatred.', 'translation': '"Sen beni tanımazsın ama ben senin kim olduğunu biliyorum!" diye hırıldadı denizci derin, yakıcı bir nefretle.', 'notes': 'burning hatred: yakıcı nefret.'}, {'id': 375, 'text': '"My name is James Vane, and Sibyl Vane was my beloved sister!"', 'translation': '"Benim adım James Vane ve Sibyl Vane benim sevgili kız kardeşimdi!"', 'notes': 'beloved sister: sevgili kız kardeş.'}, {'id': 376, 'text': "A cold dagger of fear struck straight into Dorian's heart at the mention of that long-buried tragedy.", 'translation': "O çoktan gömülmüş trajedinin anılmasıyla Dorian'ın kalbine buz gibi bir korku hançeri saplandı.", 'notes': 'dagger of fear: korku hançeri.'}, {'id': 377, 'text': '"She killed herself because of you! You broke her innocent heart and abandoned her to shame!"', 'translation': '"Senin yüzünden kendini öldürdü! Onun masum kalbini kırdın ve onu utanca terk ettin!"', 'notes': 'abandoned to shame: utanca terk etti.'}, {'id': 378, 'text': '"I swore upon my mother\'s grave that I would track you down and shoot you like a dog!"', 'translation': '"Annemin mezarı üzerine yemin ettim ki seni izini bulup bir köpek gibi vuracaktım!"', 'notes': 'track you down: izini bulmak.'}, {'id': 379, 'text': '"For eighteen long years I have sailed the oceans searching for the man she called Prince Charming!"', 'translation': '"On sekiz uzun yıl boyunca okyanuslarda onun Beyaz Atlı Prens dediği adamı arayarak yelken açtım!"', 'notes': 'sailed the oceans: okyanuslarda yelken açtı.'}, {'id': 380, 'text': '"Tonight my search has ended; say your final prayers before you die!" James shouted, cocking the hammer of the gun.', 'translation': '"Bu gece arayışım sona erdi; ölmeden önce son dualarını et!" diye haykırdı James, silahın horozunu kurarak.', 'notes': 'cocking the hammer: horozu kurarak.'}]}, {'page_no': 20, 'title': 'The Deception Under the Lamppost', 'tr_title': 'Sokak Lambası Altındaki Aldatmaca', 'vocab_focus': [('deception', 'aldatmaca, hile'), ('streetlight', 'sokak lambası'), ('youth', 'gençlik'), ('unaged', 'yaşlanmamış'), ('gullible', 'saf, kolay aldanan'), ('release', 'serbest bırakmak, salmak'), ('revelation', 'ifşa, açığa vurma'), ('pursuit', 'takip, kovalama')], 'sentences': [{'id': 381, 'text': "Even in the face of imminent death, Dorian's sharp cunning did not fail him.", 'translation': "Yaklaşan ölümün eşiğinde bile Dorian'ın keskin kurnazlığı onu yanıltmadı.", 'notes': 'sharp cunning: keskin kurnazlık.'}, {'id': 382, 'text': '"Wait! Stop! Think for a moment!" Dorian cried out with masterful calm.', 'translation': '"Bekle! Dur! Bir an düşün!" diye ustaca bir sakinlikle haykırdı Dorian.', 'notes': 'masterful calm: ustaca sakinlik.'}, {'id': 383, 'text': '"How long ago do you say your sister died? Tell me the truth!"', 'translation': '"Kız kardeşinin ne kadar zaman önce öldüğünü söylüyorsun? Bana doğruyu söyle!"', 'notes': 'tell the truth: doğruyu söylemek.'}, {'id': 384, 'text': '"Eighteen years ago!" the sailor barked, his finger tightening on the heavy trigger.', 'translation': '"On sekiz yıl önce!" diye havladı denizci, parmağı ağır tetiğin üzerinde sıkılaşarak.', 'notes': 'finger tightening: parmağı sıkılaşan.'}, {'id': 385, 'text': '"Drag me under that gas lamp, then! Look at my face before you commit murder!" Dorian insisted.', 'translation': '"Beni şu gaz lambasının altına sürükle öyleyse! Cinayet işlemeden önce yüzüme bir bak!" diye ısrar etti Dorian.', 'notes': 'commit murder: cinayet işlemek.'}, {'id': 386, 'text': "James Vane hesitated, caught by the genuine astonishment and confidence in the young man's voice.", 'translation': 'James Vane, genç adamın sesindeki sahici şaşkınlık ve özgüvenle duraksadı.', 'notes': 'genuine astonishment: sahici şaşkınlık.'}, {'id': 387, 'text': 'Roughly, the sailor hauled his prisoner toward the sickly yellow beam of the flickering streetlamp.', 'translation': 'Denizci kabaca tutsağını titrek sokak lambasının solgun sarı ışık huzmesine doğru çekti.', 'notes': 'flickering streetlamp: titrek sokak lambası.'}, {'id': 388, 'text': "As the light illuminated Dorian's countenance, James Vane stepped back with a stunned gasp of disbelief.", 'translation': "Işık Dorian'ın çehresini aydınlattığında James Vane hayret dolu bir inanamama soluğuyla geriledi.", 'notes': 'gasp of disbelief: inanamama soluğu.'}, {'id': 389, 'text': 'Before him stood a boy with bright, unwrinkled skin, radiant eyes, and the fresh cheeks of twenty years.', 'translation': 'Karşısında parlak, kırışıksız bir tene, ışıltılı gözlere ve yirmi yaşın taze yanaklarına sahip bir genç duruyordu.', 'notes': 'unwrinkled skin: kırışıksız ten.'}, {'id': 390, 'text': 'It was completely impossible that this youthful lad could have seduced a woman eighteen years earlier.', 'translation': 'Bu taze delikanlının on sekiz yıl önce bir kadını baştan çıkarmış olması kesinlikle imkansızdı.', 'notes': 'completely impossible: kesinlikle imkansız.'}, {'id': 391, 'text': '"He would be nearly forty years old! You are only a boy!" James cried in confusion, lowering the revolver.', 'translation': '"O adam neredeyse kırk yaşında olurdu! Sense henüz bir çocuksun!" diye kafa karışıklığıyla bağırdı James, tabancayı indirerek.', 'notes': 'lowering the revolver: tabancayı indirerek.'}, {'id': 392, 'text': '"Forgive me, sir! I was nearly guilty of a terrible crime against an innocent stranger," James stammered apologetically.', 'translation': '"Beni bağışlayın efendim! Az kalsın masum bir yabancıya karşı korkunç bir suç işleyecektim," diye özür dileyerek kekeledi James.', 'notes': 'stammered apologetically: özür dileyerek kekeledi.'}, {'id': 393, 'text': '"You should be careful not to let your temper mislead you into violence," Dorian said coldly, straightening his collar.', 'translation': '"Öfkenin seni şiddete sürüklemesine izin vermemek için dikkatli olmalısın," dedi Dorian soğukça, yakasını düzelterek.', 'notes': 'straightening his collar: yakasını düzelterek.'}, {'id': 394, 'text': 'Dorian turned and walked swiftly into the darkness, his heart hammering against his ribs in breathless relief.', 'translation': 'Dorian döndü ve soluksuz bir rahatlamayla kalbi kaburgalarına çarparak hızla karanlığın içine yürüdü.', 'notes': 'breathless relief: soluksuz rahatlama.'}, {'id': 395, 'text': 'James Vane stood alone beneath the flickering lamp, staring at the empty street in bitter disappointment.', 'translation': 'James Vane titrek lambanın altında yapayalnız durdu, acı bir hayal kırıklığıyla boş sokağa bakakaldı.', 'notes': 'bitter disappointment: acı hayal kırıklığı.'}, {'id': 396, 'text': 'Suddenly, the old woman who had shouted "Prince Charming" hobbled out from the alleyway toward him.', 'translation': 'Ansızın "Beyaz Atlı Prens" diye bağıran yaşlı kadın ara sokaktan ona doğru topallayarak çıktı.', 'notes': 'hobbled out: topallayarak çıktı.'}, {'id': 397, 'text': '"Why didn\'t you kill him, sailor?" the old hag cackled, clutching James by his sleeve.', 'translation': '"Onu neden öldürmedin denizci?" diye kıkırdadı koca karı, James\'in koluna yapışarak.', 'notes': 'clutching by sleeve: koluna yapışarak.'}, {'id': 398, 'text': '"He is not the man I seek! He is only twenty, and my sister died eighteen years ago!" James retorted.', 'translation': '"O aradığım adam değil! O henüz yirmi yaşında ve kız kardeşim on sekiz yıl önce öldü!" diye çıkıştı James.', 'notes': 'retorted angrily: öfkeyle karşılık verdi.'}, {'id': 399, 'text': '"Fool!" the woman spat viciously; "That man sold his soul to the devil nearly twenty years ago!"', 'translation': '"Aptal!" diye tükürdü kadın hınçla; "O adam neredeyse yirmi yıl önce ruhunu şeytana sattı!"', 'notes': 'spat viciously: hınçla tükürdü.'}, {'id': 400, 'text': '"He has looked exactly like that for eighteen years; his name is Dorian Gray, and you let him escape!"', 'translation': '"On sekiz yıldır tıpatıp öyle görünüyor; onun adı Dorian Gray ve sen onun kaçmasına izin verdin!"', 'notes': 'let him escape: kaçmasına izin verdin.'}]}, {'page_no': 21, 'title': 'Terror at Selby Royal', 'tr_title': "Selby Royal'deki Dehşet", 'vocab_focus': [('country estate', 'kır malikanesi'), ('conservatory', 'kış bahçesi, limonluk'), ('duchess', 'düşes'), ('orchid', 'orkide'), ('terror', 'dehşet, büyük korku'), ('silhouette', 'siluet, gölge'), ('collapse', 'yığılmak, bayılmak'), ('paralyze', 'felç etmek, donakalmak')], 'sentences': [{'id': 401, 'text': 'A week later, Dorian Gray was entertaining a fashionable gathering of guests at his country seat, Selby Royal.', 'translation': "Bir hafta sonra Dorian Gray, kır malikanesi Selby Royal'de seçkin bir misafir topluluğunu ağırlıyordu.", 'notes': 'entertaining guests: misafirleri ağırlayan.'}, {'id': 402, 'text': "He had fled London in acute terror, hoping the quiet countryside would shield him from James Vane's vengeance.", 'translation': "Sessiz kırsalın kendisini James Vane'in intikamından koruyacağını umarak yoğun bir dehşet içinde Londra'dan kaçmıştı.", 'notes': 'fled in terror: dehşet içinde kaçtı.'}, {'id': 403, 'text': 'Among the visitors were Lord Henry Wotton and the witty, charming Duchess of Monmouth.', 'translation': 'Ziyaretçiler arasında Lord Henry Wotton ve nüktedan, büyüleyici Monmouth Düşesi de vardı.', 'notes': 'witty duchess: nüktedan düşes.'}, {'id': 404, 'text': 'On Tuesday afternoon, Dorian was sitting with the Duchess in the warm, glass-domed conservatory.', 'translation': 'Salı öğleden sonra Dorian, sıcak ve cam kubbeli kış bahçesinde Düşes ile birlikte oturuyordu.', 'notes': 'glass-domed conservatory: cam kubbeli kış bahçesi.'}, {'id': 405, 'text': 'The air was fragrant with the exotic perfume of rare tropical orchids and blossoming camellias.', 'translation': 'Hava, nadir tropikal orkidelerin ve çiçek açmış kamelyaların egzotik kokusuyla mis gibiydi.', 'notes': 'blossoming camellias: çiçek açan kamelyalar.'}, {'id': 406, 'text': 'They were laughing playfully over tea, bantering about romance, philosophy, and the absurdities of marriage.', 'translation': 'Çay eşliğinde neşeyle gülüşüyor; aşk, felsefe ve evliliğin saçmalıkları üzerine şakalaşıyorlardı.', 'notes': 'laughing playfully: neşeyle gülüşen.'}, {'id': 407, 'text': '"Dorian, you must cut me that marvelous white orchid on the high branch," the Duchess requested coquettishly.', 'translation': '"Dorian, yüksek daldaki o harika beyaz orkideyi benim için kesmelisin," diye işveli bir edayla rica etti Düşes.', 'notes': 'requested coquettishly: işveyle rica etti.'}, {'id': 408, 'text': 'Dorian rose with a courteous bow and walked toward the tall glass wall at the far end of the greenhouse.', 'translation': 'Dorian kibar bir selamla ayağa kalktı ve seranın en ucundaki yüksek cam duvara doğru yürüdü.', 'notes': 'courteous bow: kibar selam/eğilme.'}, {'id': 409, 'text': 'As he reached up with his shears to snip the blossom, his eyes accidentally glanced through the frosted pane.', 'translation': 'Çiçeği kesmek için makasıyla yukarı uzandığı sırada gözleri kazara buzlu camın arkasına ilişti.', 'notes': 'frosted pane: buzlu cam.'}, {'id': 410, 'text': 'Pressed tightly against the cold exterior glass was a human face, watching him with burning, murderous eyes!', 'translation': 'Soğuk dış cama sıkıca yapışmış bir insan yüzü yakıcı, ölümcül gözlerle onu izliyordu!', 'notes': 'murderous eyes: ölümcül/katil gözler.'}, {'id': 411, 'text': "It was the face of James Vane, the sailor who had sworn on his sister's memory to take his life!", 'translation': "Bu, kız kardeşinin anısı üzerine onun canını almaya ant içmiş olan denizci James Vane'in yüzüydü!", 'notes': 'sworn to take life: canını almaya ant içmiş.'}, {'id': 412, 'text': "A suffocating shriek of absolute, blood-freezing horror died within Dorian's dry throat.", 'translation': "Mutlak ve kan donduran bir dehşetin boğucu çığlığı Dorian'ın kurumuş boğazında düğümlendi.", 'notes': 'blood-freezing horror: kan donduran dehşet.'}, {'id': 413, 'text': 'The garden shears clattered onto the stone floor as his knees buckled completely beneath him.', 'translation': 'Dizlerinin bağı tamamen çözülürken bahçe makası taş zemine şakırtıyla düştü.', 'notes': 'knees buckled: dizlerinin bağı çözüldü.'}, {'id': 414, 'text': 'Dorian collapsed senseless upon the ground, lying motionless among the scattered fallen petals.', 'translation': 'Dorian yere saçılmış dökülen yaprakların arasında hareketsiz yatarak bilincini yitirmiş halde yere yığıldı.', 'notes': 'collapsed senseless: bilincini yitirip yığıldı.'}, {'id': 415, 'text': 'The Duchess screamed in panic, and Lord Henry rushed in from the adjacent salon accompanied by several servants.', 'translation': 'Düşes panik içinde çığlık attı ve Lord Henry birkaç hizmetkar eşliğinde bitişikteki salondan içeri koştu.', 'notes': 'screamed in panic: panikle çığlık attı.'}, {'id': 416, 'text': 'They carried the unconscious host to his private bedchamber and summoned the local country physician.', 'translation': 'Bilinci kapalı ev sahibini özel yatak odasına taşıdılar ve yerel köy hekimini çağırdılar.', 'notes': 'unconscious host: bilinci kapalı ev sahibi.'}, {'id': 417, 'text': 'When Dorian opened his eyes hours later, he saw Lord Henry sitting quietly beside his bed.', 'translation': "Saatler sonra Dorian gözlerini açtığında yatağının yanında sessizce oturan Lord Henry'yi gördü.", 'notes': 'opened eyes: gözlerini açtı.'}, {'id': 418, 'text': '"You simply fainted from the excessive heat of the conservatory, my dear boy," Lord Henry said soothingly.', 'translation': '"Kış bahçesinin aşırı sıcağından ötürü yalnızca bayıldın sevgili dostum," dedi Lord Henry teskin edici bir sesle.', 'notes': 'excessive heat: aşırı sıcak.'}, {'id': 419, 'text': 'Dorian nodded weakly, but in his terrified mind, he knew that the specter of death was circling the house.', 'translation': 'Dorian zayıfça başını salladı fakat dehşet içindeki zihninde ölümün hayaletinin evin etrafında kol gezdiğini biliyordu.', 'notes': 'specter of death: ölümün hayaleti.'}, {'id': 420, 'text': 'James Vane had tracked him across England and was lurking in the dark woods of the estate, waiting to strike.', 'translation': 'James Vane İngiltere boyunca izini sürmüştü ve malikanenin karanlık korularında pusuya yatmış, darbe indirmeyi bekliyordu.', 'notes': 'lurking in woods: korularda pusuya yatmış.'}]}, {'page_no': 22, 'title': 'The Shooting Party and the Death in the Thicket', 'tr_title': 'Av Partisi ve Çalılıktaki Ölüm', 'vocab_focus': [('shooting', 'av, atış'), ('thicket', 'çalılık, fundalık'), ('gamekeeper', 'av bekçisi, korucu'), ('shotgun', 'av tüfeği'), ('accidental', 'kazara olan, tesadüfi'), ('corpse', 'ceset'), ('casualty', 'kazazede, kurban'), ('guilt', 'suçluluk, suç')], 'sentences': [{'id': 421, 'text': 'For two days, Dorian remained locked inside his bedchamber, consumed by a sickening, paralyzing terror.', 'translation': 'İki gün boyunca Dorian, midesini bulandıran ve felç eden bir dehşetle tükenerek yatak odasında kilitli kaldı.', 'notes': 'paralyzing terror: felç edici dehşet.'}, {'id': 422, 'text': 'He imagined footsteps outside his door, saw shadowy assassins in every corner, and started at every passing breeze.', 'translation': 'Kapısının dışında ayak sesleri hayal etti, her köşede gölgeli suikastçılar gördü ve esen her rüzgarda irkildi.', 'notes': 'started at breeze: esen rüzgardan irkildi.'}, {'id': 423, 'text': 'On the third morning, the crisp winter air and bright sunshine tempted him to leave his self-imposed prison.', 'translation': 'Üçüncü sabah, berrak kış havası ve parlak güneş ışığı kendi kendine yarattığı hapishanesini terk etmesi için onu cezbetti.', 'notes': 'self-imposed prison: kendi kendine koyduğu hapishane.'}, {'id': 424, 'text': 'The gentlemen of the party were assembling on the gravel terrace for a pheasant shoot in the home covers.', 'translation': 'Partinin beyefendileri, malikanenin korularında sülün avlamak üzere çakıllı terasta toplanıyorlardı.', 'notes': 'pheasant shoot: sülün avı.'}, {'id': 425, 'text': 'Sir Geoffrey Clouston, a renowned sportsman and crack shot, led the shooting party with jovial enthusiasm.', 'translation': 'Ünlü bir sporcu ve usta bir nişancı olan Sör Geoffrey Clouston neşeli bir hevesle av grubuna öncülük ediyordu.', 'notes': 'crack shot: usta nişancı.'}, {'id': 426, 'text': 'Dorian joined them, carrying no gun himself, merely walking beside the shooters to distract his troubled mind.', 'translation': 'Dorian tüfek taşımaksızın, yalnızca huzursuz zihnini dağıtmak için nişancıların yanında yürüyerek onlara katıldı.', 'notes': 'distract troubled mind: huzursuz zihnini dağıtmak.'}, {'id': 427, 'text': 'Gamekeepers and beaters in heavy gaiters tapped the frosty bushes with sticks, driving the birds into flight.', 'translation': 'Kalın tozluklu av korucuları ve sürücüler kuşları uçurmak için sopalarla kırağı tutmuş çalıları dövüyorlardı.', 'notes': 'driving into flight: uçuşa geçirmek.'}, {'id': 428, 'text': 'Suddenly, a large hare bounded out from a dense thicket of fern and darted across the clearing.', 'translation': 'Ansızın büyük bir yaban tavşanı yoğun bir eğrelti otu çalılığından fırladı ve açıklık boyunca ok gibi fırladı.', 'notes': 'dense thicket: yoğun çalılık.'}, {'id': 429, 'text': 'Sir Geoffrey instantly raised his double-barreled shotgun to his shoulder, taking deadly aim at the fleeing animal.', 'translation': 'Sör Geoffrey çifte namlulu av tüfeğini derhal omzuna kaldırdı, kaçan hayvana ölümcül bir şekilde nişan aldı.', 'notes': 'double-barreled shotgun: çifte namlulu av tüfeği.'}, {'id': 430, 'text': '"Do not shoot, Geoffrey! Spare its life!" Dorian cried out impulsively, seized by a strange, sudden pity.', 'translation': '"Ateş etme Geoffrey! Canını bağışla!" diye ani, tuhaf bir acımayla fevri bir şekilde haykırdı Dorian.', 'notes': 'spare its life: canını bağışlamak.'}, {'id': 431, 'text': '"What nonsense, Dorian! It is magnificent sport!" Sir Geoffrey laughed, pulling both triggers in rapid succession.', 'translation': '"Ne saçmalık Dorian! Harika bir spordur bu!" diye güldü Sör Geoffrey, ardı ardına iki tetiği de çekerek.', 'notes': 'rapid succession: ardı ardına.'}, {'id': 432, 'text': 'Two deafening blasts echoed through the frosty woodland, scattering clouds of white smoke across the clearing.', 'translation': 'İki sağır edici patlama ayazlı korulukta yankılandı, açıklığa beyaz duman bulutları saçtı.', 'notes': 'deafening blasts: sağır edici patlamalar.'}, {'id': 433, 'text': 'Simultaneously, a bloodcurdling human groan of mortal agony rang out from deep within the dense bushes!', 'translation': 'Aynı anda, yoğun çalıların derinliklerinden ölüm sancısı çeken kan dondurucu bir insan iniltisi yükseldi!', 'notes': 'mortal agony: ölüm sancısı.'}, {'id': 434, 'text': '"Good heavens! I have hit one of the beaters!" Sir Geoffrey gasped, his face draining of all color.', 'translation': '"Aman Tanrım! Sürücülerden birini vurdum!" diye soluğunu tuttu Sör Geoffrey, yüzündeki bütün renk çekilerek.', 'notes': 'hit a beater: sürücülerden birini vurdu.'}, {'id': 435, 'text': 'The keepers rushed frantically into the brambles and dragged a motionless body out onto the crisp grass.', 'translation': 'Korucular telaşla böğürtlenliklerin içine koştular ve hareketsiz bir cesedi donmuş çimlerin üzerine sürüklediler.', 'notes': 'dragged a body: bir cesedi sürükledi.'}, {'id': 436, 'text': 'The man was dead, having received the full charge of heavy buckshot directly through his chest.', 'translation': 'Ağır saçma kurşunlarının tamamını doğrudan göğsünden alan adam ölmüştü.', 'notes': 'charge of buckshot: saçma/kurşun yükü.'}, {'id': 437, 'text': '"Is he one of our estate workers?" Dorian asked with trembling lips, horrified by the tragic accident.', 'translation': '"Bizim malikane çalışanlarımızdan biri mi?" diye sordu Dorian titreyen dudaklarla, bu trajik kazadan dehşete düşerek.', 'notes': 'trembling lips: titreyen dudaklar.'}, {'id': 438, 'text': '"No, sir; he is not from this parish," the head gamekeeper replied, examining the rough, coarse clothing.', 'translation': '"Hayır efendim; bu bölgeden değil," diye yanıtladı baş korucu, kaba saba elbiseleri inceleyerek.', 'notes': 'coarse clothing: kaba saba giysiler.'}, {'id': 439, 'text': '"He looks like a sailor, sir; no one knows what he was doing concealed in the thicket."', 'translation': '"Bir denizciye benziyor efendim; çalılıkta saklanıp ne aradığını kimse bilmiyor."', 'notes': 'concealed in thicket: çalılıkta saklanmış.'}, {'id': 440, 'text': 'At the word "sailor," Dorian\'s knees went weak, and an electrifying shock of hope and dread shot through his veins.', 'translation': '"Denizci" kelimesiyle Dorian\'ın dizleri çözüldü; damarlarından elektrik çarpar gibi bir umut ve dehşet şoku geçti.', 'notes': 'shot through veins: damarlarından geçti.'}]}, {'page_no': 23, 'title': 'The Dead Sailor and the Illusion of Safety', 'tr_title': 'Ölü Denizci ve Güvende Olma İllüzyonu', 'vocab_focus': [('stable', 'ahır'), ('lantern', 'fener'), ('relief', 'rahatlama, ferahlama'), ('salvation', 'kurtuluş'), ('identification', 'kimlik tespiti, teşhis'), ('menace', 'tehdit, tehlike'), ('carriage', 'at arabası, vagon'), ('urban', 'kentsel, şehre ait')], 'sentences': [{'id': 441, 'text': "The corpse was carried to the gamekeeper's outbuilding and laid upon a rough wooden plank.", 'translation': 'Ceset korucunun müştemilatına taşındı ve kaba bir tahta kalasın üzerine yatırıldı.', 'notes': 'wooden plank: tahta kalas.'}, {'id': 442, 'text': "Dorian could not rest, tormented by the agonizing uncertainty of the dead man's identity.", 'translation': 'Ölü adamın kimliğinin kahredici belirsizliğiyle azap çeken Dorian bir türlü rahat edemiyordu.', 'notes': 'agonizing uncertainty: kahredici belirsizlik.'}, {'id': 443, 'text': 'That evening, as dusk fell over the winter park, he took a lighted lantern and walked down to the stables.', 'translation': 'O akşam kış parkının üzerine alacakaranlık çökerken yanar vaziyette bir fener aldı ve ahırlara doğru yürüdü.', 'notes': 'dusk fell: alacakaranlık çöktü.'}, {'id': 444, 'text': "The stable-boy unlocked the keeper's shed and pointed toward the covered figure in the shadowy corner.", 'translation': 'Seyis korucunun barakasının kilidini açtı ve gölgeli köşedeki üstü örtülü bedeni işaret etti.', 'notes': "keeper's shed: korucunun barakası."}, {'id': 445, 'text': 'With shaking fingers, Dorian lifted the damp linen sheet that veiled the face of the deceased.', 'translation': 'Titreyen parmaklarla Dorian, merhumun yüzünü örten nemli keten çarşafı kaldırdı.', 'notes': 'lifted the sheet: çarşafı kaldırdı.'}, {'id': 446, 'text': 'He held the lantern close, its yellow light illuminating the weathered, scarred features.', 'translation': 'Feneri yaklaştırdı; sarı ışığı yıpranmış, yara izli yüz hatlarını aydınlatıyordu.', 'notes': 'held the lantern close: feneri yaklaştırdı.'}, {'id': 447, 'text': "A sudden cry of wild joy and miraculous salvation escaped Dorian's trembling lips.", 'translation': "Dorian'ın titreyen dudaklarından ani, vahşi bir neşe ve mucizevi bir kurtuluş çığlığı döküldü.", 'notes': 'miraculous salvation: mucizevi kurtuluş.'}, {'id': 448, 'text': 'The man lying dead upon the timber was James Vane, the avenging brother of Sibyl Vane!', 'translation': "Kalasın üzerinde ölü yatan adam Sibyl Vane'in intikam peşindeki kardeşi James Vane'in ta kendisiydi!", 'notes': 'avenging brother: intikamcı kardeş.'}, {'id': 449, 'text': 'The relentless hunter who had pursued him across hundreds of miles had been struck down by a stray hunting shot!', 'translation': 'Yüzlerce mil boyunca peşinden koşan o amansız avcı serseri bir av kurşunuyla yere serilmişti!', 'notes': 'stray hunting shot: serseri av kurşunu.'}, {'id': 450, 'text': 'Dorian covered the face again, rewarded the stable-boy with gold, and walked back to the mansion weeping with relief.', 'translation': 'Dorian yüzü tekrar örttü, seyisi altınla ödüllendirdi ve rahatlamadan ağlayarak konağa geri yürüdü.', 'notes': 'weeping with relief: rahatlamadan ağlayan.'}, {'id': 451, 'text': 'He was safe; the mortal shadow that had hung over his every waking breath was lifted forever.', 'translation': 'Güvendeydi; uyanık olduğu her an üzerine çöken o ölümcül gölge ebediyen kalkmıştı.', 'notes': 'shadow was lifted: gölge kalktı.'}, {'id': 452, 'text': "No living human being remained on earth who knew his connection to Sibyl Vane's tragic demise.", 'translation': "Yeryüzünde Sibyl Vane'in trajik sonuyla olan bağlantısını bilen yaşayan hiçbir insan kalmamıştı.", 'notes': 'tragic demise: trajik son/vefat.'}, {'id': 453, 'text': "Basil Hallward was dissolved into air; James Vane lay cold in the keeper's outhouse.", 'translation': 'Basil Hallward havaya karışıp erimişti; James Vane ise korucunun müştemilatında kaskatı yatıyordu.', 'notes': 'dissolved into air: havaya karışıp eridi.'}, {'id': 454, 'text': 'The heavy burden of fear dissolved from his chest, replaced by an intoxicating surge of vitality.', 'translation': 'Korkunun ağır yükü göğsünden eriyip gitti, yerini sarhoş edici bir canlılık dalgası aldı.', 'notes': 'surge of vitality: canlılık dalgası.'}, {'id': 455, 'text': 'He ordered his carriage prepared and returned to London the following morning in buoyant spirits.', 'translation': "Faytonunun hazırlanmasını emretti ve ertesi sabah neşeli bir ruh haliyle Londra'ya döndü.", 'notes': 'buoyant spirits: neşeli/canlı ruh hali.'}, {'id': 456, 'text': 'He resolved that this miraculous escape was a divine sign that he should begin a new, virtuous life.', 'translation': 'Bu mucizevi kaçışın yeni, erdemli bir hayata başlaması gerektiğine dair ilahi bir işaret olduğuna hükmetti.', 'notes': 'virtuous life: erdemli yaşam.'}, {'id': 457, 'text': '"I will be good," he promised himself as his carriage rolled through the bustling streets of Mayfair.', 'translation': '"İyi biri olacağım," diye kendi kendine söz verdi faytonu Mayfair\'in hareketli sokaklarından geçerken.', 'notes': 'bustling streets: hareketli sokaklar.'}, {'id': 458, 'text': '"I have had too much of sin and terror; from this day forth, I shall cultivate purity and goodness."', 'translation': '"Günah ve dehşete fazlasıyla doydum; bugünden tezi yok saflık ve iyilik geliştireceğim."', 'notes': 'cultivate purity: saflık geliştirmek.'}, {'id': 459, 'text': 'He believed that by performing acts of selfless virtue, he might cleanse the corrupted portrait upstairs.', 'translation': 'Özverili erdem eylemleri sergileyerek yukarıdaki yozlaşmış portreyi arındırabileceğine inandı.', 'notes': 'selfless virtue: özverili erdem.'}, {'id': 460, 'text': 'Perhaps the painted visage would regain its youthful radiance, and his soul be restored to grace.', 'translation': 'Belki de resmedilmiş çehre gençlik ışıltısını yeniden kazanır ve ruhu lütfa kavuşurdu.', 'notes': 'restored to grace: lütfa/arınmaya kavuşmuş.'}]}, {'page_no': 24, 'title': "The Hypocrisy of Virtue and Henry's Skepticism", 'tr_title': "Erdem İkiyüzlülüğü ve Henry'nin Şüpheciliği", 'vocab_focus': [('virtue', 'erdem, fazilet'), ('hypocrisy', 'ikiyüzlülük, riyakarlık'), ('reform', 'ıslah etmek, düzelmek'), ('innocence', 'masumiyet'), ('confession', 'itiraf'), ('music', 'müzik'), ('vanity', 'kibir, gösteriş'), ('tragedy', 'trajedi, facia')], 'sentences': [{'id': 461, 'text': 'That afternoon, Dorian visited Lord Henry in his comfortable, flower-decked drawing room in Curzon Street.', 'translation': "O öğleden sonra Dorian, Curzon Sokağı'ndaki çiçeklerle donatılmış konforlu salonunda Lord Henry'yi ziyaret etti.", 'notes': 'flower-decked room: çiçeklerle donatılmış oda.'}, {'id': 462, 'text': '"Harry, I am going to be good," Dorian announced earnestly as he took a seat by the window.', 'translation': '"Harry, ben artık iyi biri olacağım," diye içtenlikle duyurdu Dorian, pencere kenarına otururken.', 'notes': 'announced earnestly: içtenlikle duyurdu.'}, {'id': 463, 'text': '"I have already begun my reformation: I did a remarkably good action only yesterday!"', 'translation': '"Islah olmaya çoktan başladım: Daha dün son derece iyi bir davranışta bulundum!"', 'notes': 'begun reformation: ıslaha başladı.'}, {'id': 464, 'text': 'Lord Henry looked at him with an amused, lazy smile: "And what was this extraordinary good action, Dorian?"', 'translation': 'Lord Henry eğlenmiş, tembel bir gülümsemeyle ona baktı: "Ve bu olağanüstü iyi davranış neydi Dorian?"', 'notes': 'amused lazy smile: eğlenmiş tembel gülümseme.'}, {'id': 465, 'text': '"I spared an innocent country girl named Hetty Merton in the village near Selby Royal,"', 'translation': '"Selby Royal yakınlarındaki köyde yaşayan Hetty Merton adında masum bir köylü kızını bağışladım,"', 'notes': 'spared an innocent girl: masum bir kızı bağışladı.'}, {'id': 466, 'text': '"She loved me passionately, and I could have easily persuaded her to run away with me to London."', 'translation': '"Beni tutkuyla seviyordu ve onu benimle Londra\'ya kaçması için kolaylıkla ikna edebilirdim."', 'notes': 'run away: kaçmak.'}, {'id': 467, 'text': '"Instead, I conquered my selfish passion and left her as pure and uncorrupted as a summer flower!"', 'translation': '"Bunun yerine bencil tutkumu yendim ve onu bir yaz çiçeği kadar saf ve lekesiz bıraktım!"', 'notes': 'conquered passion: tutkusunu yendi.'}, {'id': 468, 'text': 'Lord Henry chuckled softly, tapping his slender fingers against his silver snuffbox.', 'translation': 'Lord Henry narin parmaklarını gümüş enfiye kutusuna vurarak hafifçe kıkırdadı.', 'notes': 'chuckled softly: hafifçe kıkırdadı.'}, {'id': 469, 'text': '"My dear Dorian, your \'good action\' was simply a new form of vanity, a novel sensation of moral pride."', 'translation': '"Sevgili Dorian, senin o \'iyi davranışın\' yalnızca kibrin yeni bir biçimi, ahlaki gururun yeni bir duyumuydu."', 'notes': 'novel sensation: yeni bir duyum/his.'}, {'id': 470, 'text': '"You broke the poor girl\'s heart just as thoroughly by abandoning her as you would have by corrupting her."', 'translation': '"Onu yoldan çıkararak kıracağın gibi onu terk ederek de zavallı kızın kalbini aynı şekilde paramparça ettin."', 'notes': 'broke her heart: kalbini kırdı.'}, {'id': 471, 'text': "Dorian felt a stinging pang of disillusionment, realizing the cold truth of Lord Henry's cynical analysis.", 'translation': "Dorian, Lord Henry'nin alaycı tahlilinin soğuk gerçeğini fark ederek sızlatan bir hayal kırıklığı sancısı hissetti.", 'notes': 'pang of disillusionment: hayal kırıklığı sancısı.'}, {'id': 472, 'text': 'Lord Henry then casually changed the subject: "Have you heard that Scotland Yard has given up on Basil Hallward?"', 'translation': 'Lord Henry ardından kayıtsızca konuyu değiştirdi: "Scotland Yard\'ın Basil Hallward\'dan ümidini kestiğini duydun mu?"', 'notes': 'given up on: ümidini kesmek.'}, {'id': 473, 'text': '"They believe he was murdered in Paris or fell into the Seine from a foggy embankment."', 'translation': '"Onun Paris\'te öldürüldüğüne veya sisli bir kıyıdan Sen Nehri\'ne düştüğüne inanıyorlar."', 'notes': 'foggy embankment: sisli kıyı/set.'}, {'id': 474, 'text': '"What would you say, Harry, if I told you that I had murdered Basil?" Dorian asked suddenly, testing the waters.', 'translation': '"Sana Basil\'i benim öldürdüğümü söyleseydim ne derdin Harry?" diye ansızın sordu Dorian, ağzını arayarak.', 'notes': 'testing the waters: ağzını aramak/nabız yoklamak.'}, {'id': 475, 'text': 'Lord Henry laughed heartily: "You could never commit a murder, Dorian; crime belongs exclusively to the lower orders!"', 'translation': 'Lord Henry içtenlikle güldü: "Sen asla bir cinayet işleyemezsin Dorian; suç sadece ve sadece alt sınıflara aittir!"', 'notes': 'lower orders: alt sınıflar.'}, {'id': 476, 'text': '"Murder is too vulgar, too clumsy; you are far too artistic and refined to soil your hands with blood."', 'translation': '"Cinayet fazla kaba, fazla beceriksizcedir; ellerini kanla kirletmek için sen çok fazla sanatsal ve zarifsin."', 'notes': 'soil hands with blood: ellerini kanla kirletmek.'}, {'id': 477, 'text': '"Besides, poor Alan Campbell shot himself in his laboratory yesterday, taking his scientific secrets to the grave."', 'translation': '"Hem zavallı Alan Campbell dün laboratuvarında kendini vurdu ve bilimsel sırlarını mezara götürdü."', 'notes': 'shot himself: kendini vurdu.'}, {'id': 478, 'text': 'Dorian shuddered inwardly: another life extinguished because of the dark secret that bounded them together.', 'translation': 'Dorian için için ürperdi: Onları birbirine bağlayan karanlık sır yüzünden sönen bir başka hayat daha.', 'notes': 'life extinguished: sönen hayat.'}, {'id': 479, 'text': '"What does it profit a man if he gain the whole world and lose his own soul?" Dorian quoted in a low voice.', 'translation': '"Bir insan bütün dünyayı kazansa da kendi ruhunu kaybettikten sonra bunun ona ne faydası olur?" diye fısıldadı Dorian alçak bir sesle.', 'notes': 'lose his own soul: kendi ruhunu kaybetmek.'}, {'id': 480, 'text': '"A charming phrase, Dorian, but the soul is merely an illusion created by poets and philosophers," Lord Henry concluded.', 'translation': '"Büyüleyici bir söz Dorian fakat ruh yalnızca şairlerin ve filozofların yarattığı bir illüzyondur," diye sözünü bağladı Lord Henry.', 'notes': 'merely an illusion: yalnızca bir illüzyon.'}]}, {'page_no': 25, 'title': 'The Living Conscience and the Final Blade', 'tr_title': 'Yaşayan Vicdan ve Son Bıçak Darbesi', 'vocab_focus': [('confession', 'itiraf'), ('crimson', 'kızıl, kan kırmızısı'), ('dripping', 'damlayan'), ('frenzy', 'çılgınlık, cinnet'), ('plunge', 'saplamak, daldırmak'), ('agonizing', 'can çekişen, ızdıraplı'), ('wrinkled', 'kırışmış, buruş buruş'), ('identification', 'teşhis, kimlik tanıma')], 'sentences': [{'id': 481, 'text': 'Dorian returned home past midnight, his mind overwhelmed by an intolerable burden of torment and guilt.', 'translation': 'Dorian gece yarısından sonra eve döndü; zihni tahammül edilemez bir azap ve suçluluk yüküyle bunalmıştı.', 'notes': 'intolerable burden: tahammül edilemez yük.'}, {'id': 482, 'text': 'He dismissed his valet for the night and climbed the long stairs to the locked schoolroom.', 'translation': 'Uşağına gece için izin verdi ve kilitli okul odasına çıkan uzun merdivenleri tırmandı.', 'notes': 'dismissed for the night: gece için izin verdi.'}, {'id': 483, 'text': 'A glimmer of hope fluttered in his breast: had his mercy toward Hetty Merton softened the painted horror?', 'translation': "Göğsünde bir umut pırıltısı kıpırdandı: Hetty Merton'a gösterdiği merhamet resmedilmiş dehşeti yumuşatmış olabilir miydi?", 'notes': 'glimmer of hope: umut pırıltısı.'}, {'id': 484, 'text': 'He unlocked the door, lit the candle, and drew the purple velvet drape aside with trembling hands.', 'translation': 'Kapının kilidini açtı, mumu yaktı ve titreyen ellerle mor kadife örtüyü yana çekti.', 'notes': 'drew aside: yana çekti.'}, {'id': 485, 'text': 'A cry of pure, agonizing despair burst from his lips as he looked upon the canvas.', 'translation': 'Tuvale baktığında dudaklarından saf, kahredici bir umutsuzluk çığlığı fırladı.', 'notes': 'agonizing despair: kahredici umutsuzluk.'}, {'id': 486, 'text': 'There was no change for the better, no sign of redemption upon the monstrous, bloated countenance.', 'translation': 'O canavarca, şişkin çehrede ne iyiye doğru bir değişim ne de bir kurtuluş belirtisi vardı.', 'notes': 'change for the better: iyiye doğru değişim.'}, {'id': 487, 'text': 'If anything, the painted eyes looked even more cunning, hypocritical, and hideous than before.', 'translation': 'Aksine, resmedilmiş gözler eskisinden çok daha sinsi, ikiyüzlü ve çirkin görünüyordu.', 'notes': 'even more cunning: çok daha kurnaz/sinsi.'}, {'id': 488, 'text': 'Upon the painted hands that had held the knife, fresh, crimson blood seemed to drip onto the canvas floor!', 'translation': 'Bıçağı tutan resmedilmiş ellerin üzerinde, tuvalin zeminine taze, kızıl kan damlar gibiydi!', 'notes': 'fresh crimson blood: taze kızıl kan.'}, {'id': 489, 'text': 'Even the feet were stained with red, as if the painted figure had walked through a slaughterhouse.', 'translation': 'Sanki resmedilmiş siluet bir mezbahadan geçmiş gibi ayaklar bile kızıla boyanmıştı.', 'notes': 'slaughterhouse: mezbaha, kesimhane.'}, {'id': 490, 'text': 'Dorian fell to his knees: Lord Henry had been right; his "mercy" toward Hetty had merely been selfish vanity!', 'translation': 'Dorian dizlerinin üzerine çöktü: Lord Henry haklıydı; Hetty\'ye gösterdiği o "merhamet" yalnızca bencil bir kibirden ibaretti!', 'notes': 'selfish vanity: bencil kibir.'}, {'id': 491, 'text': 'The picture was an incorruptible, living mirror of his soul, an eternal record of his moral damnation.', 'translation': 'Resim, ruhunun bozulmaz, yaşayan bir aynası; ahlaki lanetlenmesinin ebedi bir kaydıydı.', 'notes': 'living mirror: yaşayan ayna.'}, {'id': 492, 'text': 'He could never confess his crimes; no court would believe him, and the gallows awaited his confession.', 'translation': 'Suçlarını asla itiraf edemezdi; hiçbir mahkeme ona inanmazdı ve itirafını darağacı bekliyordu.', 'notes': 'gallows awaited: darağacı bekliyordu.'}, {'id': 493, 'text': '"It has been my conscience; it has watched me night and day; I will destroy it!" Dorian shouted in madness.', 'translation': '"O benim vicdanım oldu; gece gündüz beni izledi; onu yok edeceğim!" diye delilik içinde haykırdı Dorian.', 'notes': 'shouted in madness: delilikle haykırdı.'}, {'id': 494, 'text': 'He seized the very knife that had slain Basil Hallward, its steel polished clean of old stains.', 'translation': "Eski lekelerden temizlenip parlatılmış çeliğiyle bizzat Basil Hallward'ı katleden bıçağı kaptı.", 'notes': "slain Basil: Basil'i katletmiş."}, {'id': 495, 'text': "With all the desperate fury of a condemned soul, Dorian plunged the heavy blade straight into the portrait's heart!", 'translation': 'Lanetlenmiş bir ruhun bütün çaresiz öfkesiyle Dorian ağır namluyu dosdoğru portrenin kalbine sapladı!', 'notes': 'plunged the blade: namluyu sapladı.'}, {'id': 496, 'text': 'A bloodcurdling, agonizing scream of dying torment echoed through the mansion, so terrible that the night watchman stopped outside.', 'translation': 'Ölüm ıstırabının kan donduran, can çekişen bir çığlığı konakta yankılandı; o kadar korkunçtu ki dışarıdaki gece bekçisi durakladı.', 'notes': 'dying torment: ölüm ıstırabı.'}, {'id': 497, 'text': 'Accompanied by a police constable, the terrified servants forced open the heavy schoolroom door.', 'translation': 'Dehşete kapılmış hizmetkarlar bir polis memuru eşliğinde ağır okul odası kapısını kırarak açtılar.', 'notes': 'forced open: kırarak/zorlayarak açtı.'}, {'id': 498, 'text': 'Upon the wall hung the splendid portrait of their master in all the wonder of his exquisite youth and beauty.', 'translation': 'Duvarda efendilerinin o zarif gençliğinin ve güzelliğinin bütün harikası içindeki muhteşem portresi asılı duruyordu.', 'notes': 'exquisite youth: zarif/kusursuz gençlik.'}, {'id': 499, 'text': 'Lying upon the floor was a dead man in evening dress, with a knife plunged deeply into his heart.', 'translation': 'Yerde yatan kişi ise kalbine derince bir bıçak saplanmış, gece kıyafeti giymiş ölü bir adamdı.', 'notes': 'knife plunged deeply: derince saplanmış bıçak.'}, {'id': 500, 'text': 'He was withered, wrinkled, and loathsome of visage; it was only by his exquisite rings that they recognized Dorian Gray.', 'translation': 'Buruş buruş, kırışık ve iğrenç çehreliydi; onun Dorian Gray olduğunu ancak parmaklarındaki zarif yüzüklerden teşhis edebildiler.', 'notes': 'loathsome of visage: iğrenç/tiksindirici çehreli.'}]}]
